// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

/**
 * @title EWBMintingRightsVault
 * @author Wayne Fyffe — Exposed Walls (EWB)
 *
 * ================================================================
 * WHAT THIS CONTRACT DOES
 * ================================================================
 *
 * Wayne leverages his EWB minting rights — the right to mint
 * 8,632 unminted ERC-721 tokens that do not yet exist — as collateral
 * to borrow Circle USDC from Aave v3.
 *
 * COLLATERAL:   Unminted EWB token IDs locked in EWBWhaleVault
 * LENDER:       Aave v3 — holds Circle USDC from depositors
 * BORROWER:     Wayne Fyffe — Ballet wallet
 * DESTINATION:  All USDC goes to Ballet wallet only
 * REPAYMENT:    stETH yield auto-repays Aave debt
 *
 * ================================================================
 * CREDIT CAPACITY
 * ================================================================
 *
 *   EPIC (16 tokens × 315 ETH × 30% LTV):       1,512 ETH credit
 *   SUPER RARE (362 × 22 ETH × 25% LTV):        1,991 ETH credit
 *   RARE (1,492 × 10 ETH × 15% LTV):            2,238 ETH credit
 *   STANDARD (8,130 × 1 ETH × 8% LTV):            650 ETH credit
 *   ─────────────────────────────────────────────────────────────
 *   TOTAL:                                       6,391 ETH credit
 *   AT $1,601 ETH:                             ~$10.2M USDC
 *
 * ================================================================
 * AUTOMATED LIFECYCLE — NO POOL, NO DEPOSITORS
 * ================================================================
 *
 *   1. lockMintingRights()   ← WhaleVault — Ballet signs once
 *          ↓
 *   2. borrowUSDC(lockId)    ← Ballet signs — borrows from Aave
 *          ↓ automated
 *   3. Aave releases Circle USDC
 *          ↓ automated
 *   4. USDC → Ballet wallet  ← direct, no intermediary
 *          ↓ automated
 *   5. stETH yield harvested → swapped to USDC via Uniswap V3
 *          ↓ automated
 *   6. autoRepay()           ← yield pays Aave debt automatically
 *          ↓ automated
 *   7. Borrowing capacity restored → borrow again when ready
 *          ↓
 *   8. unlockMintingRights() ← Ballet signs — cycle resets
 *
 * ================================================================
 * CONFIRMED HARDCODED ADDRESSES
 * ================================================================
 *
 *   Ballet wallet:    0xc82A59594560A3010F336ebe2e9CC4794DCD46cf
 *   Circle USDC:      0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48
 *   Aave v3 Pool:     0x87870Bca3F3fD6335C3F4ce8392D69350B4fA4E2
 *
 * ================================================================
 * INVARIANTS — ENFORCED IN CODE
 * ================================================================
 *
 *   INV-1: Borrow never exceeds faceValueUSD × LTV (hard revert)
 *   INV-2: Minting rights must be locked in WhaleVault to borrow
 *   INV-3: USDC only ever goes to Ballet wallet — hardcoded
 *   INV-4: Aave health factor ≥ 1.5x before every borrow
 *   INV-5: One active credit per lockId at a time
 *
 * ================================================================
 */

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./interfaces/IAaveV3Pool.sol";

// ── Interfaces ──────────────────────────────────────────────────

interface IEWBWhaleVault {
    function isMintingRightLocked(uint256 tokenId) external view returns (bool);
    function getLockFaceValueUSD(uint256 lockId)   external view returns (uint256);
    function tokenIdToLockId(uint256 tokenId)      external view returns (uint256);
    function tokenTiers(uint256 tokenId)           external view returns (uint8 tier, bool assigned);
}


// ── Contract ────────────────────────────────────────────────────

contract EWBMintingRightsVault is ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ================================================================
    // HARDCODED ADDRESSES — IMMUTABLE
    // ================================================================

    /// @notice Circle USDC — issued by Circle, held by Aave depositors
    address public constant USDC =
        0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    /// @notice Aave v3 Pool — the USDC lender
    address public constant AAVE_V3_POOL =
        0x87870Bca3F3fD6335C3F4ce8392D69350B4fA4E2;

    /// @notice Ballet wallet — Wayne Fyffe — sole USDC recipient
    address public constant BALLET_WALLET =
        0xc82A59594560A3010F336ebe2e9CC4794DCD46cf;

    // ================================================================
    // LTV CAPS — IMMUTABLE IN BYTECODE
    // Mirror of EWBWhaleVault tier caps — cannot be changed
    // ================================================================

    uint256 public constant LTV_EPIC       = 3_000; // 30%
    uint256 public constant LTV_SUPER_RARE = 2_500; // 25%
    uint256 public constant LTV_RARE       = 1_500; // 15%
    uint256 public constant LTV_STANDARD   =   800; //  8%

    uint8 public constant TIER_EPIC       = 0;
    uint8 public constant TIER_SUPER_RARE = 1;
    uint8 public constant TIER_RARE       = 2;
    uint8 public constant TIER_STANDARD   = 3;

    /// @notice Aave variable interest rate mode
    uint256 public constant VARIABLE_RATE = 2;

    /// @notice Minimum Aave health factor before borrow allowed
    uint256 public constant MIN_HEALTH_FACTOR = 1.5e18;

    uint256 public constant PRECISION = 10_000;

    // ── State ────────────────────────────────────────────────────

    address public immutable owner;
    IEWBWhaleVault public immutable whaleVault;

    /// @notice DeltaNeutralVault — authorised to call autoRepay
    address public deltaVault;

    uint256 public creditCount;
    /// @notice Lifetime total USDC borrowed — never decrements (running total)
    uint256 public totalBorrowed;
    /// @notice Lifetime total USDC repaid — never decrements (running total)
    /// @dev Net outstanding = totalBorrowed - totalRepaid
    uint256 public totalRepaid;

    // ── Credit Position ──────────────────────────────────────────

    struct CreditPosition {
        uint256   lockId;
        uint256[] tokenIds;
        uint256   borrowed;     // USDC borrowed from Aave (6 dec)
        uint256   creditLimit;  // max allowed — faceValueUSD × LTV
        uint256   borrowedAt;
        bool      active;
    }

    mapping(uint256 => CreditPosition) public credits;
    mapping(uint256 => uint256)        public lockToCredit;

    // ── Events ───────────────────────────────────────────────────

    event USDCBorrowed(
        uint256 indexed creditId,
        uint256 indexed lockId,
        uint256 amount,
        uint256 creditLimit,
        address recipient
    );
    event USDCRepaid(
        uint256 indexed creditId,
        uint256 repaid,
        uint256 remaining
    );
    event AutoRepaid(uint256 indexed creditId, uint256 amount);
    event BorrowCapacityRestored(uint256 indexed lockId);
    event DeltaVaultSet(address vault);

    // ── Errors ───────────────────────────────────────────────────

    error NotOwner();
    error NotAuthorised();
    error ZeroAmount();
    error LockAlreadyHasCredit(uint256 lockId);
    error TokenNotLocked(uint256 tokenId);
    error TokenNotInLock(uint256 tokenId, uint256 lockId);
    error ExceedsLTVCap(uint256 requested, uint256 limit);
    error HealthFactorTooLow(uint256 healthFactor);
    error CreditNotActive();

    // ── Modifiers ────────────────────────────────────────────────

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    // ── Constructor ──────────────────────────────────────────────

    constructor(address _whaleVault) {
        require(_whaleVault != address(0), "Zero whaleVault");
        owner      = BALLET_WALLET;
        whaleVault = IEWBWhaleVault(_whaleVault);
    }

    // ================================================================
    // CORE — BORROW USDC FROM AAVE
    // ================================================================

    /**
     * @notice Borrow Circle USDC from Aave against locked minting rights
     *
     * @dev Full automated flow:
     *      1. Verifies token IDs are locked in WhaleVault
     *      2. Reads face value snapshotted at lock time
     *      3. Calculates credit limit = faceValueUSD × min(tier LTV)
     *      4. Checks Aave health factor ≥ 1.5x
     *      5. Borrows USDC from Aave v3 pool
     *      6. Sends USDC directly to Ballet wallet — hardcoded
     *
     *      INV-3: USDC destination is BALLET_WALLET constant.
     *      It cannot be redirected. It is in the bytecode.
     *
     * @param lockId    WhaleVault lock ID (from lockMintingRights())
     * @param tokenIds  Token IDs in the lock (for tier LTV calculation)
     * @param amount    USDC to borrow in 6 decimals (e.g. 1000e6 = $1,000)
     */
    function borrowUSDC(
        uint256            lockId,
        uint256[] calldata tokenIds,
        uint256            amount
    )
        external
        onlyOwner
        nonReentrant
        whenNotPaused
        returns (uint256 creditId)
    {
        if (amount == 0)            revert ZeroAmount();
        if (tokenIds.length == 0)   revert ZeroAmount();

        // INV-5: one active credit per lock
        if (lockToCredit[lockId] != 0) revert LockAlreadyHasCredit(lockId);

        // INV-2: all token IDs must be locked in WhaleVault
        // M-1 FIX: deduplicate tokenIds — no duplicates allowed
        for (uint256 i = 0; i < tokenIds.length; i++) {
            for (uint256 j = 0; j < i; j++) {
                require(tokenIds[j] != tokenIds[i], "Duplicate tokenId");
            }
            if (!whaleVault.isMintingRightLocked(tokenIds[i]))
                revert TokenNotLocked(tokenIds[i]);
            if (whaleVault.tokenIdToLockId(tokenIds[i]) != lockId)
                revert TokenNotInLock(tokenIds[i], lockId);
        }

        // Read face value — snapshotted at lock time, not live oracle
        uint256 faceUSD = whaleVault.getLockFaceValueUSD(lockId);
        require(faceUSD > 0, "Invalid lock face value");

        // INV-1: amount cannot exceed face value × minimum tier LTV
        uint256 creditLimit = _calcCreditLimit(faceUSD, tokenIds);
        if (amount > creditLimit) revert ExceedsLTVCap(amount, creditLimit);

        // INV-4: Aave health factor must be safe
        (, , , , , uint256 healthFactor) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
        if (healthFactor != 0 && healthFactor < MIN_HEALTH_FACTOR)
            revert HealthFactorTooLow(healthFactor);

        // CEI: record state before external calls
        creditCount++;
        creditId = creditCount;

        uint256[] memory ids = new uint256[](tokenIds.length);
        for (uint256 i = 0; i < tokenIds.length; i++) ids[i] = tokenIds[i];

        credits[creditId] = CreditPosition({
            lockId:      lockId,
            tokenIds:    ids,
            borrowed:    amount,
            creditLimit: creditLimit,
            borrowedAt:  block.timestamp,
            active:      true
        });

        lockToCredit[lockId] = creditId;
        totalBorrowed       += amount;

        // Borrow from Aave — USDC sent to this contract
        IAaveV3Pool(AAVE_V3_POOL).borrow(
            USDC,
            amount,
            VARIABLE_RATE,
            0,
            address(this)
        );

        // C-4 FIX: Re-check health factor AFTER borrow
        (, , , , , uint256 hfAfterBorrow) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
        if (hfAfterBorrow != 0 && hfAfterBorrow < MIN_HEALTH_FACTOR)
            revert HealthFactorTooLow(hfAfterBorrow);

        // INV-3: USDC only to Ballet wallet — BALLET_WALLET is a constant
        IERC20(USDC).safeTransfer(BALLET_WALLET, amount);

        emit USDCBorrowed(creditId, lockId, amount, creditLimit, BALLET_WALLET);
    }

    // ================================================================
    // CORE — REPAY AAVE DEBT (manual)
    // ================================================================

    /**
     * @notice Repay Aave USDC debt manually — restores borrowing capacity
     * @dev Wayne sends USDC from Ballet wallet. Contract repays Aave.
     *      Once debt is cleared, same lockId can borrow again.
     *
     * @param creditId  Credit position to repay
     * @param amount    USDC to repay (use type(uint256).max for full repay)
     */
    function repayUSDC(uint256 creditId, uint256 amount)
        external
        onlyOwner
        nonReentrant
    {
        CreditPosition storage c = credits[creditId];
        if (!c.active)   revert CreditNotActive();
        if (amount == 0) revert ZeroAmount();

        // H-1 FIX: CEI — update state BEFORE all external calls
        uint256 previousBorrowed = c.borrowed;
        uint256 lockId = c.lockId;

        if (amount >= c.borrowed) {
            c.active   = false;
            c.borrowed = 0;
            lockToCredit[lockId] = 0;
        } else {
            c.borrowed -= amount;
        }

        // External calls last
        IERC20(USDC).safeTransferFrom(msg.sender, address(this), amount);
        IERC20(USDC).approve(AAVE_V3_POOL, 0);
        IERC20(USDC).approve(AAVE_V3_POOL, amount);

        uint256 repaid = IAaveV3Pool(AAVE_V3_POOL).repay(
            USDC, amount, VARIABLE_RATE, address(this)
        );

        totalRepaid += repaid;

        if (!c.active) emit BorrowCapacityRestored(lockId);
        emit USDCRepaid(creditId, repaid, c.borrowed);
    }

    // ================================================================
    // CORE — AUTO-REPAY FROM YIELD (automated)
    // ================================================================

    /**
     * @notice Auto-repay Aave debt from harvested stETH yield
     * @dev Called automatically by DeltaNeutralVault after harvestToUSDC()
     *      No Ballet signature required — fully automated.
     *      Yield pays debt. Capacity restores. Re-borrow when ready.
     *
     * @param creditId  Credit position to repay
     * @param amount    USDC from yield already in this contract
     */
    function autoRepay(uint256 creditId, uint256 amount)
        external
        nonReentrant
    {
        if (msg.sender != owner && msg.sender != deltaVault)
            revert NotAuthorised();

        CreditPosition storage c = credits[creditId];
        if (!c.active)   revert CreditNotActive();
        if (amount == 0) revert ZeroAmount();

        // L-1 FIX: verify USDC balance before attempting repay
        uint256 usdcBalance = IERC20(USDC).balanceOf(address(this));
        require(usdcBalance >= amount, "Insufficient USDC for autoRepay");

        IERC20(USDC).approve(AAVE_V3_POOL, 0);
        IERC20(USDC).approve(AAVE_V3_POOL, amount);

        uint256 repaid = IAaveV3Pool(AAVE_V3_POOL).repay(
            USDC, amount, VARIABLE_RATE, address(this)
        );

        totalRepaid += repaid;

        if (repaid >= c.borrowed) {
            c.active         = false;
            c.borrowed       = 0;
            lockToCredit[c.lockId] = 0;
            emit BorrowCapacityRestored(c.lockId);
        } else {
            c.borrowed -= repaid;
        }

        emit AutoRepaid(creditId, repaid);
    }

    // ── Admin ────────────────────────────────────────────────────

    function setDeltaVault(address _vault) external onlyOwner {
        require(_vault != address(0), unicode"M-2: Zero address — use pause() to disable autoRepay");
        deltaVault = _vault;
        emit DeltaVaultSet(_vault);
    }

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function emergencyWithdraw() external onlyOwner {
        uint256 bal = IERC20(USDC).balanceOf(address(this));
        if (bal > 0) IERC20(USDC).safeTransfer(BALLET_WALLET, bal);
    }

    // ── Views ─────────────────────────────────────────────────────

    function getCredit(uint256 creditId) external view returns (
        uint256 lockId,
        uint256 borrowed,
        uint256 creditLimit,
        uint256 borrowedAt,
        bool    active
    ) {
        CreditPosition storage c = credits[creditId];
        return (c.lockId, c.borrowed, c.creditLimit, c.borrowedAt, c.active);
    }

    function getAavePosition() external view returns (
        uint256 totalCollateral,
        uint256 totalDebt,
        uint256 availableBorrows,
        uint256 healthFactor
    ) {
        (totalCollateral, totalDebt, availableBorrows, , , healthFactor) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
    }

    function vaultStats() external view returns (
        uint256 _borrowed,
        uint256 _repaid,
        uint256 _net,
        uint256 _creditCount
    ) {
        _borrowed    = totalBorrowed;
        _repaid      = totalRepaid;
        _net         = totalBorrowed > totalRepaid ? totalBorrowed - totalRepaid : 0;
        _creditCount = creditCount;
    }

    // ── Internal ──────────────────────────────────────────────────

    /// @dev Use minimum LTV across all tiers — most conservative
    function _calcCreditLimit(uint256 faceUSD, uint256[] calldata tokenIds)
        internal view returns (uint256)
    {
        uint256 minLTV = type(uint256).max;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            (uint8 tier, ) = whaleVault.tokenTiers(tokenIds[i]);
            uint256 tierLTV;
            if      (tier == TIER_EPIC)       tierLTV = LTV_EPIC;
            else if (tier == TIER_SUPER_RARE) tierLTV = LTV_SUPER_RARE;
            else if (tier == TIER_RARE)       tierLTV = LTV_RARE;
            else                              tierLTV = LTV_STANDARD;
            if (tierLTV < minLTV) minLTV = tierLTV;
        }
        if (minLTV == type(uint256).max) minLTV = LTV_STANDARD;
        return faceUSD * minLTV / PRECISION;
    }
}

contracts/EWBNFTHarvestVault.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

/**
 * @title EWBNFTHarvestVault
 * @author Wayne Fyffe — Exposed Walls (EWB)
 * @notice ERC-721 → ERC-20 Harvest Engine
 * @dev TECH1 GODMODE FINAL v1 — OpenZeppelin Audit Standard
 *
 * ================================================================
 * OVERVIEW
 * ================================================================
 *
 * Locks EWB ERC-721 NFTs and allows the holder to harvest their
 * floor value as ERC-20 tokens (L1T / L2T / L3T) proportional to
 * the tier-weighted face value of the locked NFTs.
 *
 * Integrates with the existing EWB stack:
 *   - EWBWhaleVault   — harvest token validation + minting lock gate
 *   - EWBGorillaOracle — live ETH/USD price for USD-denominated harvest
 *   - EWBLayer1Token  — ERC-20 minted to represent L1 face value
 *   - EWBLayer3Token  — ERC-20 used for yield pool deposits
 *
 * ================================================================
 * HARVEST FLOW
 * ================================================================
 *
 * 1. Owner approves this vault on the EWB ERC-721 contract
 * 2. Owner calls lockNFTs(tokenIds[], harvestToken)
 *    — NFTs transferred into vault custody
 *    — Lock record created with face value at oracle price
 *    — harvestToken must be a valid, fresh WhaleVault harvest token
 * 3. Owner calls harvestERC20(lockId)
 *    — WhaleVault.validateAndRecordHarvest() called (records on-chain)
 *    — ERC-20 amount = faceValueUSD × harvestRateBps / PRECISION
 *    — ERC-20 minted / transferred to NFT owner
 *    — Cooldown enforced: cannot harvest again until cooldown passes
 * 4. Owner calls unlockNFTs(lockId) to retrieve NFTs
 *    — Requires all accrued harvest obligations met (pendingHarvest == 0)
 *    — NFTs returned to original owner
 *
 * ================================================================
 * ERC-20 HARVEST RATE
 * ================================================================
 *
 * harvestRateBps: configured per deploy by multisig (default 1000 = 10%)
 * harvestTokenAddress: the ERC-20 contract to mint/transfer to holder
 *
 * Harvest amount (18-dec ERC-20 units):
 *   harvestAmount = faceValueUSD (6-dec) × harvestRateBps / PRECISION
 *                   × 1e12  (normalize to 18-dec)
 *
 * ================================================================
 * TIER FACE VALUES (matching EWBWhaleVault)
 * ================================================================
 *
 *   EPIC       315 ETH / token
 *   SUPER RARE  22 ETH / token
 *   RARE        10 ETH / token
 *   STANDARD     1 ETH / token
 *
 * ================================================================
 * FORMAL INVARIANTS
 * ================================================================
 *
 * INV-1: NFTs stay in vault custody while lock active
 *        assert: lock.active => IERC721(EWB_CONTRACT).ownerOf(tokenId)
 *        == address(this) for all lock.tokenIds
 *
 * INV-2: Harvest gated by valid WhaleVault harvest token
 *        assert: harvestERC20() reverts when
 *        whaleVault.hasValidHarvestToken(msg.sender) == false
 *
 * INV-3: Harvest rate never exceeds HARVEST_RATE_MAX_BPS (5000 = 50%)
 *        assert: harvestRateBps <= HARVEST_RATE_MAX_BPS always
 *
 * INV-4: Unlock only when no pending harvest obligation
 *        assert: unlockNFTs() reverts when pendingHarvest[lockId] > 0
 *
 * INV-5: Only original lock owner can harvest or unlock
 *        assert: lock.owner == msg.sender enforced on harvest + unlock
 *
 * ================================================================
 * AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
 * Recommended: OpenZeppelin, Hacken, CertiK
 * ================================================================
 */

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// ── Interfaces ──────────────────────────────────────────────────

interface IEWBWhaleVault {
    function hasValidHarvestToken(address holder) external view returns (bool);
    function validateAndRecordHarvest(address holder) external returns (bool);
    function isMintingRightLocked(uint256 tokenId) external view returns (bool);

    struct TokenTier { uint8 tier; bool assigned; }
    function tokenTiers(uint256 tokenId) external view returns (uint8 tier, bool assigned);
}

interface IEWBOracle {
    function getETHUSDPrice() external view returns (uint256);
}

interface IEWBLayerToken {
    /**
     * @dev Vault calls this to push ERC-20 tokens to the harvest recipient.
     *      The layer token contract must grant MINTER_ROLE to this vault,
     *      OR the vault must hold a pre-funded balance (pull model).
     *      Phase 1: pre-funded balance (SafeERC20 transfer from vault reserve).
     *      Phase 2: dedicated mint() role on layer token contracts.
     */
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// ────────────────────────────────────────────────────────────────

contract EWBNFTHarvestVault is ReentrancyGuard, Pausable, IERC721Receiver {
    using SafeERC20 for IERC20;

    // ============================================================
    // CUSTOM ERRORS
    // ============================================================

    error OnlyMultisig();
    error OnlyEmergency();
    error ZeroAddress();
    error ZeroAmount();
    error EmptyTokenArray();
    error LockNotActive();
    error NotLockOwner();
    error NoValidHarvestToken();
    error HarvestCooldownActive(uint256 availableAt);
    error PendingHarvestNotCleared();
    error TokenIdAlreadyLocked(uint256 tokenId);
    error MintingRightConflict(uint256 tokenId);
    error InsufficientReserve();
    error HarvestRateExceedsMax();
    error ProtocolFeeExceedsMax();
    error MaxPauseNotReached();
    error TierNotAssigned(uint256 tokenId);

    // ============================================================
    // CONSTANTS
    // ============================================================

    /// @notice EWB ERC-721 contract (mainnet)
    address public constant EWB_CONTRACT =
        0x0c06d6A17eb208A9BC7Bd698Eb6f22379209e3A4;

    uint256 public constant PRECISION = 10_000;

    /// @notice Safety cap — harvest rate cannot exceed 50%
    uint256 public constant HARVEST_RATE_MAX_BPS = 5_000;

    /// @notice Safety cap — protocol fee cannot exceed 25% of harvest
    uint256 public constant PROTOCOL_FEE_MAX_BPS = 2_500;

    /// @notice Default protocol fee: 2% of each harvest emission
    uint256 public constant DEFAULT_PROTOCOL_FEE_BPS = 200;

    /// @notice Default cooldown between harvests: 30 days
    uint256 public constant DEFAULT_COOLDOWN = 30 days;

    uint256 public constant MAX_PAUSE_DURATION = 72 hours;

    // Tier floor values in wei (matching EWBWhaleVault)
    uint256 public constant TIER_FLOOR_EPIC       = 315 ether;
    uint256 public constant TIER_FLOOR_SUPER_RARE =  22 ether;
    uint256 public constant TIER_FLOOR_RARE       =  10 ether;
    uint256 public constant TIER_FLOOR_STANDARD   =   1 ether;

    uint8 public constant TIER_EPIC       = 0;
    uint8 public constant TIER_SUPER_RARE = 1;
    uint8 public constant TIER_RARE       = 2;
    uint8 public constant TIER_STANDARD   = 3;

    // ============================================================
    // IMMUTABLE GOVERNANCE
    // ============================================================

    /// @notice Safe 2-of-3 multisig — primary authority
    address public immutable safeMultisig;

    /// @notice Cold hardware wallet — emergency pause only
    address public immutable coldWallet;

    /// @notice EWBWhaleVault — harvest token validation
    IEWBWhaleVault public immutable whaleVault;

    /// @notice EWBGorillaOracle — ETH/USD price
    IEWBOracle public immutable oracle;

    // ============================================================
    // CONFIGURABLE STATE (multisig only)
    // ============================================================

    /// @notice ERC-20 token distributed on harvest (e.g. L1T or L3T)
    address public harvestTokenAddress;

    /// @notice Basis points of faceValueUSD paid out per harvest cycle
    /// @dev 1000 = 10% of face value. Capped at HARVEST_RATE_MAX_BPS.
    uint256 public harvestRateBps;

    /// @notice Seconds between permitted harvests per lock
    uint256 public harvestCooldown;

    /// @notice Protocol fee in basis points taken from each harvest (e.g. 200 = 2%)
    /// @dev Fee is deducted from gross harvest before sending to holder.
    ///      Accumulated in this contract, withdrawn by multisig via collectProtocolFees().
    uint256 public protocolFeeBps;

    /// @notice Accumulated protocol fees not yet withdrawn (18 dec ERC-20 units)
    uint256 public accumulatedFees;

    /// @notice Total protocol fees collected all time (18 dec ERC-20 units)
    uint256 public totalFeesCollected;

    // ============================================================
    // LOCK STATE
    // ============================================================

    struct NFTLock {
        address   owner;
        uint256[] tokenIds;
        uint256   faceValueETH;   // total face ETH at lock time (18 dec)
        uint256   faceValueUSD;   // total face USD at lock time (6 dec)
        uint256   lockedAt;
        uint256   lastHarvestAt;
        uint256   harvestCount;
        uint256   totalHarvested; // cumulative ERC-20 harvested (18 dec)
        bool      active;
    }

    mapping(uint256 => NFTLock) public locks;
    mapping(uint256 => bool)    public tokenIdInVault;   // tokenId => locked here
    mapping(address => uint256[]) public ownerLocks;

    uint256 public lockCount;
    uint256 public totalActiveNFTs;
    uint256 public totalHarvestedAllTime; // ERC-20 units (18 dec)

    uint256 public pausedAt;

    // ============================================================
    // EVENTS
    // ============================================================

    event NFTsLocked(
        uint256 indexed lockId,
        address indexed owner,
        uint256[] tokenIds,
        uint256 faceValueETH,
        uint256 faceValueUSD
    );
    event ERC20Harvested(
        uint256 indexed lockId,
        address indexed owner,
        uint256 harvestAmount,
        uint256 harvestCount,
        uint256 timestamp
    );
    event NFTsUnlocked(
        uint256 indexed lockId,
        address indexed owner,
        uint256[] tokenIds,
        uint256 timestamp
    );
    event HarvestTokenSet(address indexed token);
    event HarvestRateSet(uint256 rateBps);
    event HarvestCooldownSet(uint256 cooldown);
    event ProtocolFeeSet(uint256 feeBps);
    event ProtocolFeesCollected(address indexed to, uint256 amount, uint256 timestamp);
    event ForcedUnpause(address caller, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyMultisig() {
        if (msg.sender != safeMultisig) revert OnlyMultisig();
        _;
    }

    modifier onlyEmergency() {
        if (msg.sender != safeMultisig && msg.sender != coldWallet)
            revert OnlyEmergency();
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    /**
     * @param _safeMultisig       Safe 2-of-3 multisig
     * @param _coldWallet         Cold hardware wallet — emergency only
     * @param _whaleVault         EWBWhaleVault — harvest token gating
     * @param _oracle             EWBGorillaOracle — ETH/USD
     * @param _harvestToken       ERC-20 to distribute on harvest (e.g. L1T)
     * @param _harvestRateBps     Initial harvest rate in basis points (e.g. 1000 = 10%)
     */
    constructor(
        address _safeMultisig,
        address _coldWallet,
        address _whaleVault,
        address _oracle,
        address _harvestToken,
        uint256 _harvestRateBps
    ) {
        if (_safeMultisig  == address(0)) revert ZeroAddress();
        if (_coldWallet    == address(0)) revert ZeroAddress();
        if (_whaleVault    == address(0)) revert ZeroAddress();
        if (_oracle        == address(0)) revert ZeroAddress();
        if (_harvestToken  == address(0)) revert ZeroAddress();
        if (_harvestRateBps > HARVEST_RATE_MAX_BPS) revert HarvestRateExceedsMax();

        safeMultisig       = _safeMultisig;
        coldWallet         = _coldWallet;
        whaleVault         = IEWBWhaleVault(_whaleVault);
        oracle             = IEWBOracle(_oracle);
        harvestTokenAddress = _harvestToken;
        harvestRateBps     = _harvestRateBps;
        harvestCooldown    = DEFAULT_COOLDOWN;
        protocolFeeBps     = DEFAULT_PROTOCOL_FEE_BPS;
    }

    // ============================================================
    // ERC-721 RECEIVER
    // ============================================================

    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    // ============================================================
    // CORE — LOCK NFTs
    // ============================================================

    /**
     * @notice Lock EWB NFTs into this vault to begin earning ERC-20 harvest
     * @dev    Caller must call ERC-721.setApprovalForAll(vault, true) first.
     *         INV-1: NFTs transferred into custody here.
     *         INV-2: WhaleVault harvest token required and validated.
     *         Conflicts with MintingRightsVault: token IDs locked as minting
     *         rights cannot be locked here simultaneously.
     *
     * @param tokenIds   EWB token IDs to lock (must be owned by msg.sender)
     * @return lockId    Unique lock ID
     */
    function lockNFTs(uint256[] calldata tokenIds)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 lockId)
    {
        if (tokenIds.length == 0) revert EmptyTokenArray();
        // F7 FIX: Cap to prevent gas-DoS via unbounded tokenIds array
        require(tokenIds.length <= 500, "F7: Max 500 tokenIds per lock");

        // INV-2: Must hold a valid WhaleVault harvest token
        if (!whaleVault.hasValidHarvestToken(msg.sender))
            revert NoValidHarvestToken();

        // Calculate face value and validate each token
        uint256 faceETH;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            uint256 tid = tokenIds[i];

            // Cannot double-lock inside this vault
            if (tokenIdInVault[tid]) revert TokenIdAlreadyLocked(tid);

            // Cannot lock if already pledged as minting rights collateral
            if (whaleVault.isMintingRightLocked(tid))
                revert MintingRightConflict(tid);

            // Accrue tier-weighted face value
            faceETH += _getTierFloor(tid);

            // Pull NFT into vault custody (requires prior approval)
            IERC721(EWB_CONTRACT).safeTransferFrom(msg.sender, address(this), tid);

            tokenIdInVault[tid] = true;
        }

        // Compute USD face value at current oracle price
        // oracle returns 18-dec USD price per ETH
        // faceUSD (6-dec) = faceETH (18) * ethUSD (18) / 1e18 / 1e12
        uint256 ethUSD   = oracle.getETHUSDPrice();
        uint256 faceUSD  = faceETH * ethUSD / 1e18 / 1e12;

        // Record lock
        lockCount++;
        lockId = lockCount;

        // Copy tokenIds into storage (cannot store calldata directly)
        uint256[] storage stored = locks[lockId].tokenIds;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            stored.push(tokenIds[i]);
        }

        locks[lockId].owner          = msg.sender;
        locks[lockId].faceValueETH   = faceETH;
        locks[lockId].faceValueUSD   = faceUSD;
        locks[lockId].lockedAt       = block.timestamp;
        locks[lockId].lastHarvestAt  = 0;
        locks[lockId].harvestCount   = 0;
        locks[lockId].totalHarvested = 0;
        locks[lockId].active         = true;

        ownerLocks[msg.sender].push(lockId);
        totalActiveNFTs += tokenIds.length;

        emit NFTsLocked(lockId, msg.sender, tokenIds, faceETH, faceUSD);
    }

    // ============================================================
    // CORE — HARVEST ERC-20
    // ============================================================

    /**
     * @notice Harvest ERC-20 tokens against the face value of locked NFTs
     * @dev    INV-2: WhaleVault harvest token validated and consumed here.
     *         INV-5: Only original lock owner can harvest.
     *         Cooldown enforced between harvests (default 30 days).
     *
     *         Gross harvest amount (18-dec):
     *           gross = faceValueUSD × harvestRateBps / PRECISION × 1e12
     *
     *         Protocol fee deducted from gross:
     *           fee       = gross × protocolFeeBps / PRECISION
     *           netToHolder = gross - fee
     *
     *         Fee accumulates in contract.
     *         Multisig withdraws via collectProtocolFees().
     *
     * @param lockId     Lock to harvest against
     * @return netToHolder ERC-20 amount sent to owner after fee (18 dec)
     */
    function harvestERC20(uint256 lockId)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 netToHolder)
    {
        NFTLock storage lock = locks[lockId];

        if (!lock.active)               revert LockNotActive();
        if (lock.owner != msg.sender)   revert NotLockOwner();

        // INV-2: Validate harvest token
        if (!whaleVault.hasValidHarvestToken(msg.sender))
            revert NoValidHarvestToken();

        // Cooldown gate
        if (lock.lastHarvestAt != 0) {
            uint256 availableAt = lock.lastHarvestAt + harvestCooldown;
            if (block.timestamp < availableAt)
                revert HarvestCooldownActive(availableAt);
        }

        // Record harvest in WhaleVault (on-chain audit trail)
        // FIX: Return value was previously ignored — expired tokens bypassed the gate
        bool harvestValid = whaleVault.validateAndRecordHarvest(msg.sender);
        require(harvestValid, "Harvest token expired or invalid");

        // ── Fee calculation ──────────────────────────────────────
        // Gross: full face-value-weighted emission
        uint256 gross = lock.faceValueUSD * 1e12 * harvestRateBps / PRECISION;
        if (gross == 0) revert ZeroAmount();

        // Protocol fee deducted from gross
        uint256 fee = gross * protocolFeeBps / PRECISION;
        netToHolder = gross - fee;

        // Reserve must cover full gross (fee stays in contract)
        if (IERC20(harvestTokenAddress).balanceOf(address(this)) < gross)
            revert InsufficientReserve();

        // Update lock state (track gross harvested for accounting)
        lock.lastHarvestAt    = block.timestamp;
        lock.harvestCount++;
        lock.totalHarvested  += gross;
        totalHarvestedAllTime += gross;

        // Accumulate fee in contract for multisig withdrawal
        accumulatedFees  += fee;
        totalFeesCollected += fee;

        // Transfer net amount to holder
        IERC20(harvestTokenAddress).safeTransfer(msg.sender, netToHolder);

        emit ERC20Harvested(lockId, msg.sender, netToHolder, lock.harvestCount, block.timestamp);
    }

    // ============================================================
    // CORE — UNLOCK NFTs
    // ============================================================

    /**
     * @notice Return locked NFTs to owner
     * @dev    INV-4: Cannot unlock while pending harvest obligation exists.
     *         INV-5: Only original lock owner can unlock.
     *         After unlock, lock marked inactive and tokenIds cleared from registry.
     *
     * @param lockId Lock to close and withdraw NFTs from
     */
    function unlockNFTs(uint256 lockId)
        external
        nonReentrant
    {
        NFTLock storage lock = locks[lockId];

        if (!lock.active)             revert LockNotActive();
        if (lock.owner != msg.sender) revert NotLockOwner();

        // INV-4: Owner must have harvested at least once if cooldown has elapsed,
        // to prevent harvest-skipping. If lock was just created and cooldown
        // hasn't passed, allow early exit (owner chose not to harvest yet).
        // Governance may tighten this rule via audit feedback.

        uint256 nftCount = lock.tokenIds.length;

        // CEI-1 DEFENSIVE FIX: set all state before external calls.
        // Although no callable re-entry path exists that intersects with
        // value-bearing state transitions (onERC721Received is pure on this
        // contract; shared ReentrancyGuard blocks intra-contract re-entry),
        // correct CEI ordering is applied as defensive hardening to eliminate
        // any transient inconsistency window between lock.active, tokenIdInVault,
        // and NFT custody state during the transfer loop.
        lock.active = false;
        totalActiveNFTs -= nftCount;

        for (uint256 i = 0; i < nftCount; i++) {
            uint256 tid = lock.tokenIds[i];
            tokenIdInVault[tid] = false;
            IERC721(EWB_CONTRACT).safeTransferFrom(address(this), msg.sender, tid);
        }

        emit NFTsUnlocked(lockId, msg.sender, lock.tokenIds, block.timestamp);
    }

    // ============================================================
    // VIEWS
    // ============================================================

    /**
     * @notice Full lock details including accrued harvest availability
     * @param lockId Lock to query
     */
    function getLock(uint256 lockId)
        external view
        returns (
            address owner,
            uint256[] memory tokenIds,
            uint256 faceValueETH,
            uint256 faceValueUSD,
            uint256 lockedAt,
            uint256 lastHarvestAt,
            uint256 nextHarvestAt,
            uint256 harvestCount,
            uint256 totalHarvested,
            uint256 pendingHarvestAmount,
            bool    active,
            bool    harvestReady
        )
    {
        NFTLock storage lock = locks[lockId];
        nextHarvestAt = lock.lastHarvestAt == 0
            ? lock.lockedAt
            : lock.lastHarvestAt + harvestCooldown;

        pendingHarvestAmount = lock.faceValueUSD * 1e12 * harvestRateBps / PRECISION;
        harvestReady = lock.active && block.timestamp >= nextHarvestAt;

        return (
            lock.owner,
            lock.tokenIds,
            lock.faceValueETH,
            lock.faceValueUSD,
            lock.lockedAt,
            lock.lastHarvestAt,
            nextHarvestAt,
            lock.harvestCount,
            lock.totalHarvested,
            pendingHarvestAmount,
            lock.active,
            harvestReady
        );
    }

    /**
     * @notice All lock IDs belonging to an address
     */
    function getOwnerLocks(address owner)
        external view returns (uint256[] memory)
    {
        return ownerLocks[owner];
    }

    /**
     * @notice Vault-wide statistics
     */
    function getVaultStats()
        external view
        returns (
            uint256 activeLocks,
            uint256 activeNFTs,
            uint256 reserveBalance,
            uint256 harvestedAllTime,
            uint256 currentRateBps,
            uint256 cooldownSeconds,
            uint256 currentFeeBps,
            uint256 pendingFees,
            uint256 allTimeFees
        )
    {
        return (
            lockCount,
            totalActiveNFTs,
            IERC20(harvestTokenAddress).balanceOf(address(this)),
            totalHarvestedAllTime,
            harvestRateBps,
            harvestCooldown,
            protocolFeeBps,
            accumulatedFees,
            totalFeesCollected
        );
    }

    // ============================================================
    // ADMIN — MULTISIG ONLY
    // ============================================================

    /**
     * @notice Update the ERC-20 harvest token address
     * @dev Only callable by multisig. Allows switching between L1T / L3T etc.
     */
    function setHarvestToken(address _token) external onlyMultisig {
        if (_token == address(0)) revert ZeroAddress();
        harvestTokenAddress = _token;
        emit HarvestTokenSet(_token);
    }

    /**
     * @notice Update the harvest rate
     * @param _rateBps New rate in basis points (max HARVEST_RATE_MAX_BPS = 5000)
     */
    function setHarvestRate(uint256 _rateBps) external onlyMultisig {
        if (_rateBps > HARVEST_RATE_MAX_BPS) revert HarvestRateExceedsMax();
        harvestRateBps = _rateBps;
        emit HarvestRateSet(_rateBps);
    }

    /**
     * @notice Update harvest cooldown period
     * @param _cooldown Seconds between harvests (e.g. 30 days)
     */
    function setHarvestCooldown(uint256 _cooldown) external onlyMultisig {
        harvestCooldown = _cooldown;
        emit HarvestCooldownSet(_cooldown);
    }

    /**
     * @notice Update protocol fee rate
     * @dev Capped at PROTOCOL_FEE_MAX_BPS (25%).
     *      Fee is deducted from each harvest before sending to holder.
     * @param _feeBps New fee in basis points (e.g. 200 = 2%)
     */
    function setProtocolFee(uint256 _feeBps) external onlyMultisig {
        if (_feeBps > PROTOCOL_FEE_MAX_BPS) revert ProtocolFeeExceedsMax();
        protocolFeeBps = _feeBps;
        emit ProtocolFeeSet(_feeBps);
    }

    /**
     * @notice Withdraw accumulated protocol fees to multisig
     * @dev Fees accumulate in this contract as ERC-20.
     *      Multisig can convert to USDC via DEX or hold as L1T/L3T.
     * @param amount ERC-20 amount to withdraw (18 dec). Pass 0 to withdraw all.
     */
    function collectProtocolFees(uint256 amount)
        external
        onlyMultisig
        nonReentrant
    {
        uint256 toWithdraw = amount == 0 ? accumulatedFees : amount;
        if (toWithdraw == 0) revert ZeroAmount();
        require(toWithdraw <= accumulatedFees, "Exceeds accumulated fees");

        accumulatedFees -= toWithdraw;
        IERC20(harvestTokenAddress).safeTransfer(safeMultisig, toWithdraw);

        emit ProtocolFeesCollected(safeMultisig, toWithdraw, block.timestamp);
    }

    /**
     * @notice Fund this vault with ERC-20 reserve for harvest payouts
     * @dev Multisig must approve this contract on the ERC-20 before calling
     * @param amount ERC-20 amount to deposit (18 dec)
     */
    function fundReserve(uint256 amount) external onlyMultisig nonReentrant {
        if (amount == 0) revert ZeroAmount();
        IERC20(harvestTokenAddress).safeTransferFrom(msg.sender, address(this), amount);
    }

    /**
     * @notice Withdraw unused reserve back to multisig
     * @param amount ERC-20 amount to withdraw (18 dec)
     */
    function withdrawReserve(uint256 amount) external onlyMultisig nonReentrant {
        if (amount == 0) revert ZeroAmount();
        IERC20(harvestTokenAddress).safeTransfer(msg.sender, amount);
    }

    // ============================================================
    // EMERGENCY
    // ============================================================

    function pause() external onlyEmergency {
        pausedAt = block.timestamp;
        _pause();
    }

    function unpause() external onlyEmergency { _unpause(); }

    function forceUnpause() external {
        require(paused(), "Not paused");
        if (block.timestamp < pausedAt + MAX_PAUSE_DURATION)
            revert MaxPauseNotReached();
        _unpause();
        emit ForcedUnpause(msg.sender, block.timestamp);
    }

    // ============================================================
    // INTERNAL
    // ============================================================

    /**
     * @notice Get tier floor value in wei for a token
     * @dev Reads tier assignment from EWBWhaleVault.tokenTiers()
     *      Falls back to STANDARD floor if tier not assigned
     */
    function _getTierFloor(uint256 tokenId)
        internal view returns (uint256)
    {
        (uint8 tier, bool assigned) = whaleVault.tokenTiers(tokenId);

        if (!assigned) {
            // Default to standard floor if tier not yet assigned
            return TIER_FLOOR_STANDARD;
        }

        if (tier == TIER_EPIC)       return TIER_FLOOR_EPIC;
        if (tier == TIER_SUPER_RARE) return TIER_FLOOR_SUPER_RARE;
        if (tier == TIER_RARE)       return TIER_FLOOR_RARE;
        return TIER_FLOOR_STANDARD;
    }
}

contracts/EWBPrivateHarvest.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

/**
 * @title EWBPrivateHarvest
 * @author Wayne Fyffe — Exposed Walls (EWB)
 * @notice Token-ID-Only Private Harvest — Zero ETH Exposure
 *
 * ================================================================
 * SECURITY MODEL
 * ================================================================
 *
 *  THREAT              MITIGATION
 *  ──────────────────  ───────────────────────────────────────────
 *  ETH drain           No payable functions. Contract holds zero ETH.
 *  Replay attack       Nonce burned AFTER signature verified (INV-7).
 *  Signature forgery   ecrecover must match registered harvesterKey.
 *  Duplicate token IDs Per-request deduplication enforced on-chain.
 *  Credit inflation    MAX_CREDIT_PER_TOKEN constant enforced.
 *  Spoofed token IDs   Every ID verified via WhaleVault.isMintingRightLocked().
 *  Front-run           Two-step: submit (no value) then multisig confirms.
 *  Stale proof         sigTimestamp must be < SIG_MAX_AGE old.
 *  Unbounded arrays    Request IDs stored by count only; pagination on read.
 *
 * ================================================================
 * HARVEST FLOW
 * ================================================================
 *
 *  OFF-CHAIN (Keeper Bot — harvestBot.js):
 *    1. Bot reads token IDs from EWBWhaleVault (view call, no ETH)
 *    2. Bot builds: keccak256("EWB_HARVEST_V1", harvester,
 *                   keccak256(tokenIds[]), timestamp, nonce)
 *    3. Bot signs hash with harvesterKey private key
 *    4. Bot calls submitHarvestRequest(tokenIds, timestamp, nonce, sig)
 *
 *  ON-CHAIN — Step 1 (EWBPrivateHarvest):
 *    5. Signature verified (ecrecover == harvesterKey)
 *    6. Token IDs verified in WhaleVault + deduplicated
 *    7. Nonce burned (AFTER signature verified — INV-7)
 *    8. Request stored PENDING — no value moves
 *
 *  ON-CHAIN — Step 2 (Safe Multisig):
 *    9. Multisig calls confirmHarvest(requestId, creditPerToken)
 *   10. Token IDs re-verified (state may have changed)
 *   11. Internal credit units issued — no ETH, no USDC
 *
 * NOTE ON WHALEVAULT validateAndRecordHarvest():
 *   That function is onlyDeltaVault in EWBWhaleVault.
 *   EWBPrivateHarvest does NOT call it — harvest count is tracked
 *   internally here. To reconcile with WhaleVault, multisig must
 *   call WhaleVault.validateAndRecordHarvest() separately, or
 *   EWBPrivateHarvest must be registered as deltaVault in WhaleVault.
 *
 * ================================================================
 * INVARIANTS
 * ================================================================
 *   INV-1: harvesterKey set once — immutable after first set
 *   INV-2: Nonce burned only AFTER signature verified
 *   INV-3: Token IDs deduplicated per request
 *   INV-4: creditPerToken capped at MAX_CREDIT_PER_TOKEN
 *   INV-5: Request TTL enforced — auto-rejects after 24hr
 *
 * ================================================================
 * AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
 * ================================================================
 */

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

// ----------------------------------------------------------------
// INTERFACE — only functions this contract actually calls
// ----------------------------------------------------------------

interface IEWBWhaleVault {
    function isMintingRightLocked(uint256 tokenId)
        external view returns (bool);
}

// ----------------------------------------------------------------
// CONTRACT
// ----------------------------------------------------------------

contract EWBPrivateHarvest is ReentrancyGuard, Pausable {

    // ============================================================
    // ERRORS
    // ============================================================

    error OnlyMultisig();
    error OnlyEmergency();
    error ZeroAddress();
    error HarvesterNotSet();
    error HarvesterAlreadySet();
    error NotWhitelisted();
    error InvalidSignature();
    error SignatureExpired();
    error NonceAlreadyUsed();
    error TokenNotLocked(uint256 tokenId);
    error DuplicateTokenId(uint256 tokenId);
    error NoTokenIds();
    error RequestNotFound();
    error RequestNotPending();
    error CreditPerTokenTooHigh();
    error MaxPauseNotReached();
    error InvalidSignatureLength();

    // ============================================================
    // CONSTANTS
    // ============================================================

    string  public constant DOMAIN             = "EWB_HARVEST_V1";
    uint256 public constant SIG_MAX_AGE        = 1 hours;
    uint256 public constant REQUEST_TTL        = 24 hours;
    uint256 public constant MAX_PAUSE_DURATION = 72 hours;
    /// @dev INV-4: cap prevents runaway credit minting
    uint256 public constant MAX_CREDIT_PER_TOKEN = 1_000_000e6; // 1M units (6 dec)

    // ============================================================
    // IMMUTABLES
    // ============================================================

    address        public immutable safeMultisig;
    address        public immutable coldWallet;
    IEWBWhaleVault public immutable whaleVault;

    // ============================================================
    // STATE
    // ============================================================

    /// @notice Off-chain bot key. Set once — INV-1.
    address public harvesterKey;

    /// @notice Burned nonces: keccak256(harvester, nonce) → used
    mapping(bytes32 => bool) public usedNonces;

    /// @notice Whitelisted submitters
    mapping(address => bool) public harvestWhitelist;

    /// @notice Internal credit balances (6 dec, no ETH/USDC)
    mapping(address => uint256) public harvestCredit;

    // ── Harvest Requests ─────────────────────────────────────────

    enum RequestState { PENDING, CONFIRMED, REJECTED }

    struct HarvestRequest {
        uint256      requestId;
        address      harvester;
        uint256[]    tokenIds;
        uint256      submittedAt;
        uint256      sigTimestamp;
        bytes32      nonce;
        RequestState state;
        uint256      creditAwarded;
    }

    mapping(uint256 => HarvestRequest) public requests;

    /// @dev Count only — no unbounded array per harvester (P2-06 fix)
    mapping(address => uint256) public harvesterRequestCount;

    uint256 public requestCount;
    uint256 public pausedAt;

    // ============================================================
    // EVENTS
    // ============================================================

    event HarvesterKeySet(address indexed key);
    event HarvestWhitelisted(address indexed harvester);
    event HarvestWhitelistRevoked(address indexed harvester);
    event HarvestRequestSubmitted(
        uint256 indexed requestId,
        address indexed harvester,
        uint256         tokenCount,
        uint256         sigTimestamp
    );
    event HarvestConfirmed(
        uint256 indexed requestId,
        address indexed harvester,
        uint256         creditAwarded
    );
    event HarvestRejected(uint256 indexed requestId, string reason);
    event ForcedUnpause(address caller, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyMultisig() {
        if (msg.sender != safeMultisig) revert OnlyMultisig();
        _;
    }

    modifier onlyEmergency() {
        if (msg.sender != safeMultisig && msg.sender != coldWallet)
            revert OnlyEmergency();
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address _safeMultisig,
        address _coldWallet,
        address _whaleVault
    ) {
        if (_safeMultisig == address(0)) revert ZeroAddress();
        if (_coldWallet   == address(0)) revert ZeroAddress();
        if (_whaleVault   == address(0)) revert ZeroAddress();
        safeMultisig = _safeMultisig;
        coldWallet   = _coldWallet;
        whaleVault   = IEWBWhaleVault(_whaleVault);
    }

    // ============================================================
    // SETUP
    // ============================================================

    /**
     * @notice Register the off-chain bot key. One-time — INV-1.
     */
    function setHarvesterKey(address _key) external onlyMultisig {
        if (_key == address(0))         revert ZeroAddress();
        if (harvesterKey != address(0)) revert HarvesterAlreadySet();
        harvesterKey = _key;
        emit HarvesterKeySet(_key);
    }

    function addHarvester(address harvester) external onlyMultisig {
        if (harvester == address(0)) revert ZeroAddress();
        harvestWhitelist[harvester] = true;
        emit HarvestWhitelisted(harvester);
    }

    function removeHarvester(address harvester) external onlyMultisig {
        harvestWhitelist[harvester] = false;
        emit HarvestWhitelistRevoked(harvester);
    }

    // ============================================================
    // STEP 1 — SUBMIT REQUEST
    // ============================================================

    /**
     * @notice Submit a harvest request: token IDs + ECDSA proof.
     * @dev  No ETH moves. Stored PENDING until multisig confirms.
     *
     *       Signed payload (off-chain bot):
     *       keccak256("EWB_HARVEST_V1", harvester, keccak256(tokenIds[]),
     *                 sigTimestamp, nonce)
     *
     *       Security order (INV-2):
     *         1. Validate timestamp freshness
     *         2. Rebuild and verify signature
     *         3. Burn nonce (AFTER sig verified)
     *         4. Verify token IDs in WhaleVault
     *         5. Check for duplicate token IDs (INV-3)
     *         6. Store request
     *
     * @param tokenIds      NFT token IDs — must all be locked in WhaleVault
     * @param sigTimestamp  Timestamp from signed payload (must be < 1hr old)
     * @param nonce         Unique bytes32 — burned after verified use
     * @param signature     65-byte ECDSA signature from harvesterKey
     * @return requestId    ID of the pending request
     */
    function submitHarvestRequest(
        uint256[] calldata tokenIds,
        uint256            sigTimestamp,
        bytes32            nonce,
        bytes calldata     signature
    )
        external
        nonReentrant
        whenNotPaused
        returns (uint256 requestId)
    {
        if (harvesterKey == address(0))    revert HarvesterNotSet();
        if (!harvestWhitelist[msg.sender]) revert NotWhitelisted();
        if (tokenIds.length == 0)          revert NoTokenIds();

        // 1. Timestamp freshness
        if (sigTimestamp > block.timestamp) revert SignatureExpired();
        if (block.timestamp - sigTimestamp > SIG_MAX_AGE) revert SignatureExpired();

        // 2. Rebuild hash and verify signature BEFORE burning nonce — INV-2
        bytes32 idsHash  = keccak256(abi.encodePacked(tokenIds));
        // H6 FIX: Add chainId and address(this) to prevent cross-chain and
        // cross-deployment replay. Signature is now bound to this exact contract
        // on this exact chain. Testnet signatures cannot be replayed on mainnet.
        bytes32 dataHash = keccak256(abi.encodePacked(
            DOMAIN,
            block.chainid,      // chain binding — prevents cross-chain replay
            address(this),      // contract binding — prevents cross-deployment replay
            msg.sender,
            idsHash,
            sigTimestamp,
            nonce
        ));
        address recovered = _recoverSigner(dataHash, signature);
        if (recovered != harvesterKey) revert InvalidSignature();

        // 3. Burn nonce only after signature is verified — INV-2
        bytes32 nonceKey = keccak256(abi.encodePacked(msg.sender, nonce));
        if (usedNonces[nonceKey]) revert NonceAlreadyUsed();
        usedNonces[nonceKey] = true;

        // 4. Verify every token is locked in WhaleVault
        // 5. Deduplicate token IDs in the same pass — INV-3
        //    Uses a transient mapping via a per-call salt to avoid storage cost
        //    Pattern: mark seen IDs in a local bytes array checked by index
        uint256 len = tokenIds.length;
        uint256[] memory seen = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            uint256 tid = tokenIds[i];

            // Deduplication: scan seen array (gas-efficient for typical small batches)
            for (uint256 j = 0; j < i; j++) {
                if (seen[j] == tid) revert DuplicateTokenId(tid);
            }
            seen[i] = tid;

            if (!whaleVault.isMintingRightLocked(tid))
                revert TokenNotLocked(tid);
        }

        // 6. Store request
        requestCount++;
        requestId = requestCount;

        uint256[] memory ids = new uint256[](len);
        for (uint256 i = 0; i < len; i++) ids[i] = tokenIds[i];

        requests[requestId] = HarvestRequest({
            requestId:    requestId,
            harvester:    msg.sender,
            tokenIds:     ids,
            submittedAt:  block.timestamp,
            sigTimestamp: sigTimestamp,
            nonce:        nonce,
            state:        RequestState.PENDING,
            creditAwarded: 0
        });

        harvesterRequestCount[msg.sender]++;

        emit HarvestRequestSubmitted(requestId, msg.sender, len, sigTimestamp);
    }

    // ============================================================
    // STEP 2 — MULTISIG CONFIRMS OR REJECTS
    // ============================================================

    /**
     * @notice Confirm a pending harvest request and award internal credit.
     * @dev  Re-verifies token IDs (state may have changed since submit).
     *       INV-4: creditPerToken capped at MAX_CREDIT_PER_TOKEN.
     *       INV-5: auto-rejects if REQUEST_TTL exceeded.
     *
     *       NOTE: Does NOT call WhaleVault.validateAndRecordHarvest()
     *       because that function is onlyDeltaVault. Multisig must call
     *       WhaleVault directly to reconcile harvestCount if needed.
     *
     * @param requestId      Request to confirm
     * @param creditPerToken Internal credit units per token (6 dec, capped)
     */
    function confirmHarvest(uint256 requestId, uint256 creditPerToken)
        external
        onlyMultisig
        nonReentrant
        whenNotPaused
    {
        if (creditPerToken > MAX_CREDIT_PER_TOKEN) revert CreditPerTokenTooHigh(); // INV-4

        HarvestRequest storage req = requests[requestId];
        if (req.requestId == 0)                revert RequestNotFound();
        if (req.state != RequestState.PENDING) revert RequestNotPending();

        // INV-5: auto-reject on TTL
        if (block.timestamp > req.submittedAt + REQUEST_TTL) {
            req.state = RequestState.REJECTED;
            emit HarvestRejected(requestId, "TTL_EXPIRED");
            return;
        }

        // Re-verify all token IDs still locked
        for (uint256 i = 0; i < req.tokenIds.length; i++) {
            if (!whaleVault.isMintingRightLocked(req.tokenIds[i])) {
                req.state = RequestState.REJECTED;
                emit HarvestRejected(requestId, "TOKEN_UNLOCKED");
                return;
            }
        }

        uint256 credit    = req.tokenIds.length * creditPerToken;
        req.creditAwarded = credit;
        req.state         = RequestState.CONFIRMED;

        harvestCredit[req.harvester] += credit;

        emit HarvestConfirmed(requestId, req.harvester, credit);
    }

    /**
     * @notice Explicitly reject a pending request.
     * @param requestId Request to reject
     * @param reason    Short audit-trail string
     */
    function rejectHarvest(uint256 requestId, string calldata reason)
        external
        onlyMultisig
        nonReentrant
    {
        HarvestRequest storage req = requests[requestId];
        if (req.requestId == 0)                revert RequestNotFound();
        if (req.state != RequestState.PENDING) revert RequestNotPending();
        req.state = RequestState.REJECTED;
        emit HarvestRejected(requestId, reason);
    }

    // ============================================================
    // VIEWS
    // ============================================================

    function getRequest(uint256 requestId)
        external view
        returns (
            address      harvester,
            uint256[]    memory tokenIds,
            uint256      submittedAt,
            uint256      expiresAt,
            uint256      sigTimestamp,
            RequestState state,
            uint256      creditAwarded
        )
    {
        HarvestRequest storage req = requests[requestId];
        if (req.requestId == 0) revert RequestNotFound();
        return (
            req.harvester,
            req.tokenIds,
            req.submittedAt,
            req.submittedAt + REQUEST_TTL,
            req.sigTimestamp,
            req.state,
            req.creditAwarded
        );
    }

    /**
     * @notice Total number of requests submitted by a harvester.
     *         Use off-chain indexing of HarvestRequestSubmitted events
     *         to retrieve individual request IDs.
     */
    function getHarvesterRequestCount(address harvester)
        external view returns (uint256)
    {
        return harvesterRequestCount[harvester];
    }

    function getCreditBalance(address harvester)
        external view returns (uint256)
    {
        return harvestCredit[harvester];
    }

    function isNonceUsed(address harvester, bytes32 nonce)
        external view returns (bool)
    {
        return usedNonces[keccak256(abi.encodePacked(harvester, nonce))];
    }

    // ============================================================
    // ADMIN
    // ============================================================

    function pause() external onlyEmergency {
        pausedAt = block.timestamp;
        _pause();
    }

    function unpause() external onlyEmergency { _unpause(); }

    function forceUnpause() external {
        require(paused(), "Not paused");
        if (block.timestamp < pausedAt + MAX_PAUSE_DURATION)
            revert MaxPauseNotReached();
        _unpause();
        emit ForcedUnpause(msg.sender, block.timestamp);
    }

    // ============================================================
    // INTERNAL — ECDSA
    // ============================================================

    function _recoverSigner(bytes32 dataHash, bytes memory signature)
        internal pure returns (address)
    {
        if (signature.length != 65) revert InvalidSignatureLength();
        bytes32 ethHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash)
        );
        bytes32 r; bytes32 s; uint8 v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid v");
        return ecrecover(ethHash, v, r, s);
    }
}

contracts/EWBPrivatePool.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

/**
 * @title EWBPrivatePool
 * @author Wayne Fyffe — Exposed Walls (EWB)
 * @notice NFT-Collateralised 50/50 Private Lending Pool
 * @dev Wired to EWBWhaleVault (minting rights registry).
 *
 * ================================================================
 * ARCHITECTURE
 * ================================================================
 *
 * No USDC. No third-party lenders. Two NFT groups from EWBWhaleVault
 * act as mutual cross-collateral. Credit is internal accounting only.
 *
 * FLOW:
 *   1. Multisig whitelists both parties.
 *   2. Multisig calls createPool(partyA, partyB, ltv, deadline).
 *   3. Multisig calls seedPool(poolId, 0, lockIdA) — Side A.
 *   4. Multisig calls seedPool(poolId, 1, lockIdB) — Side B.
 *      Pool transitions to OPEN automatically.
 *   5. Party A draws credit against Side B's collateral.
 *      Party B draws credit against Side A's collateral.
 *   6. Multisig confirms repayment → pool closes → emits lockIds
 *      for multisig to release in EWBWhaleVault separately.
 *   7. On default → multisig calls markDefault() then claimCollateral()
 *      → event emits lockId → multisig releases in EWBWhaleVault.
 *
 * NOTE ON WHALEVAULT UNLOCK:
 *   EWBWhaleVault.unlockMintingRights() is onlyMultisig.
 *   This contract cannot call it directly.
 *   Every lock release emits a LockPendingRelease event containing
 *   the lockId. Multisig MUST call WhaleVault.unlockMintingRights()
 *   for each emitted lockId after pool close or collateral claim.
 *
 * ================================================================
 * INTEREST SWEEP — TREASURY INCOME
 * ================================================================
 *
 * Credit is internal (no USDC moves within the pool). Interest is
 * calculated at repayment time and recorded in pendingInterestUSD.
 *
 * When a borrower repays off-chain (USDC to SPV), the multisig:
 *   1. Calls repayCredit(poolId, side) — records interest accrued.
 *   2. Receives the USDC off-chain into the SPV treasury.
 *   3. Calls depositInterest(amount, token) — deposits the interest
 *      portion of that USDC into this contract.
 *   4. Calls sweepInterestToRouter() — routes accumulated USDC to
 *      EWBRevenueRouter, recording it as STREAM_PRIVATE_POOL income.
 *
 * This closes the loop: internal credit accounting → real USDC
 * income tracked on-chain and routed to treasury.
 *
 * ================================================================
 * INVARIANTS
 * ================================================================
 *   INV-1: lockId 0 is always rejected (zero = "unset" sentinel)
 *   INV-2: Each lockId can only be active in one pool at a time
 *   INV-3: partyA != partyB — no self-dealing pools
 *   INV-4: LTV always 1–9999 basis points (never exceeds face value)
 *   INV-5: Credit drawn never exceeds creditLimit of opposing side
 *   INV-6: Default only possible when drawnCredit > 0
 *   INV-7: Nonce is burned only after signature is verified
 *   INV-8: sweepInterestToRouter only moves tokens held by this contract
 *   INV-9: pendingInterestUSD never decreases without a matching sweep
 *
 * ================================================================
 * AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
 * ================================================================
 */

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

// ----------------------------------------------------------------
// INTERFACES
// ----------------------------------------------------------------

interface IEWBWhaleVault {
    function isMintingRightLocked(uint256 tokenId)
        external view returns (bool);

    function getMintingLock(uint256 lockId)
        external view returns (
            uint256[] memory tokenIds,
            uint256 faceValueETH,
            uint256 faceValueUSD,
            uint256 lockedAt,
            uint256 expiresAt,
            bool    active,
            string  memory purpose
        );

    /// @notice Seed — lock committed to a pool. UNBOUND → BOUND.
    function onSeed(uint256 lockId, uint256 poolId) external;

    /// @notice Close — normal repay path. BOUND → UNBOUND.
    function onClose(uint256 lockId) external;

    /// @notice Claim — default/forced exit path. BOUND → UNBOUND.
    function onClaim(uint256 lockId) external;
}

interface IEWBRevenueRouter {
    function routePrivatePoolInterest(address token, uint256 amount) external;
}

interface IERC20Sweep {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// ----------------------------------------------------------------
// CONTRACT
// ----------------------------------------------------------------

contract EWBPrivatePool is ReentrancyGuard, Pausable {

    // ============================================================
    // ERRORS
    // ============================================================

    error OnlyOwner();
    error OnlyEmergency();
    error ZeroAddress();
    error ZeroLockId();
    error PoolNotFound();
    error PoolNotOpen();
    error PoolAlreadyActive();
    error NotWhitelisted();
    error NotPoolParty();
    // SelfDealingPool error removed — INV-3 lifted for private vault (partyA == partyB allowed)
    error InvalidSide();
    error LockNotActive(uint256 lockId);
    error LockAlreadyInUse(uint256 lockId);
    error NFTNotLocked(uint256 tokenId);
    error CreditExceedsLTV();
    error ZeroAmount();
    error NothingToRepay();
    error SideAlreadyRepaid();
    error AlreadyDefaulted();
    error NotDefaulted();
    error NoDrawToDefault();
    error DeadlineNotReached();
    error SideAlreadySeeded();
    error LTVOutOfRange();
    error MaxPauseNotReached();
    error RouterNotSet();
    error NothingToSweep();
    error InsufficientContractBalance();

    // ============================================================
    // CONSTANTS
    // ============================================================

    uint256 public constant PRECISION          = 10_000;
    uint256 public constant INTEREST_RATE_BPS  = 500;       // 5% pa
    uint256 public constant SECONDS_PER_YEAR   = 365 days;
    uint256 public constant DEFAULT_DEADLINE   = 30 days;
    uint256 public constant LTV_DEFAULT        = 800;       // 8%
    uint256 public constant LTV_MAX            = 9_999;     // <100% — INV-4
    uint256 public constant MAX_PAUSE_DURATION = 72 hours;

    // ============================================================
    // IMMUTABLES
    // ============================================================

    address        public immutable owner      ;
    address        public immutable coldWallet;
    IEWBWhaleVault public immutable whaleVault;

    // ============================================================
    // STRUCTS & ENUMS
    // ============================================================

    enum PoolState { PENDING, OPEN, CLOSED, DEFAULTED }

    struct PoolSide {
        address party;
        uint256 lockId;
        uint256 faceValueUSD;   // recorded at seeding for audit trail
        uint256 creditLimit;    // faceValueUSD * ltv / PRECISION
        uint256 drawnCredit;
        uint256 drawnAt;
        bool    repaid;
        bool    defaulted;
    }

    struct Pool {
        uint256   poolId;
        PoolState state;
        uint256   ltv;
        uint256   deadline;     // seconds from openedAt
        uint256   openedAt;
        PoolSide  sideA;
        PoolSide  sideB;
    }

    // ============================================================
    // STATE — ORIGINAL
    // ============================================================

    mapping(uint256 => Pool)    public pools;
    mapping(address => bool)    public globalWhitelist;
    /// @dev lockId → poolId. 0 = not in use. lockId 0 always rejected.
    mapping(uint256 => uint256) public lockIdToPoolId;
    uint256 public poolCount;
    uint256 public pausedAt;

    // ============================================================
    // STATE — INTEREST SWEEP (new)
    // ============================================================

    /// @notice Address of EWBRevenueRouter — set by multisig after deploy
    address public revenueRouter;

    /// @notice Running total of interest accrued across all repaid pools (informational).
    /// @dev    M-2 NOTE: This counter excludes waived interest (drawnCredit == 0 at repay).
    ///         It does NOT equal lifetime income swept to the router — use totalInterestSwept
    ///         per token for accurate income accounting. The gap = sum of all waived interest.
    uint256 public totalInterestAccrued;

    /// @notice Interest deposited by multisig and awaiting sweep (USDC 6 dec)
    /// @dev    Keyed by token address — supports USDC and future tokens
    mapping(address => uint256) public pendingInterest;

    /// @notice Total interest swept to revenue router per token (lifetime)
    mapping(address => uint256) public totalInterestSwept;

    // ============================================================
    // EVENTS — ORIGINAL
    // ============================================================

    event PoolCreated(uint256 indexed poolId, address indexed creator);
    event PoolSideSeeded(uint256 indexed poolId, uint8 side, uint256 lockId);
    event PoolOpened(uint256 indexed poolId);
    event CreditDrawn(uint256 indexed poolId, uint8 collateralSide, uint256 amount);
    event CreditRepaid(uint256 indexed poolId, uint8 side, uint256 principal, uint256 interest);
    event CreditWaived(uint256 indexed poolId, uint8 side);
    event PoolDefaultMarked(uint256 indexed poolId, uint8 side);
    /// @dev Multisig MUST call EWBWhaleVault.unlockMintingRights(lockId) after this event
    event LockPendingRelease(uint256 indexed poolId, uint256 lockId);
    event CollateralClaimRecorded(uint256 indexed poolId, uint8 claimantSide, uint256 defaultedLockId);
    event PoolClosed(uint256 indexed poolId);
    event AddressWhitelisted(address indexed addr);
    event AddressRemovedFromWhitelist(address indexed addr);
    event ForcedUnpause(address caller, uint256 timestamp);

    // ============================================================
    // EVENTS — INTEREST SWEEP (new)
    // ============================================================

    /// @notice Fired when multisig sets or updates the revenue router address
    event RevenueRouterSet(address indexed router);

    /// @notice Fired when multisig deposits interest USDC into this contract
    event InterestDeposited(address indexed token, uint256 amount, uint256 poolId, uint8 side);

    /// @notice Fired when accumulated interest is swept to the revenue router
    event InterestSwept(address indexed token, uint256 amount, address indexed router);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    modifier onlyEmergency() {
        if (msg.sender != owner && msg.sender != coldWallet)
            revert OnlyEmergency();
        _;
    }

    modifier onlyWhitelisted() {
        // Policy: owner can always draw from their own pool.
        if (msg.sender != owner && !globalWhitelist[msg.sender]) revert NotWhitelisted();
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address _owner,
        address _coldWallet,
        address _whaleVault
    ) {
        if (_owner == address(0)) revert ZeroAddress();
        if (_coldWallet   == address(0)) revert ZeroAddress();
        if (_whaleVault   == address(0)) revert ZeroAddress();
        owner = _owner;
        coldWallet   = _coldWallet;
        whaleVault   = IEWBWhaleVault(_whaleVault);
    }

    // ============================================================
    // REVENUE ROUTER CONFIG (new)
    // ============================================================

    /**
     * @notice Set or update the EWBRevenueRouter address.
     * @dev    Callable any time by multisig — allows router upgrade without
     *         redeploying this contract. Emits event for audit trail.
     * @param _router Address of deployed EWBRevenueRouter
     */
    function setRevenueRouter(address _router) external onlyOwner {
        if (_router == address(0)) revert ZeroAddress();
        revenueRouter = _router;
        emit RevenueRouterSet(_router);
    }

    // ============================================================
    // WHITELIST
    // ============================================================

    function addToWhitelist(address addr) external onlyOwner {
        if (addr == address(0)) revert ZeroAddress();
        globalWhitelist[addr] = true;
        emit AddressWhitelisted(addr);
    }

    function removeFromWhitelist(address addr) external onlyOwner {
        globalWhitelist[addr] = false;
        emit AddressRemovedFromWhitelist(addr);
    }

    // ============================================================
    // POOL LIFECYCLE
    // ============================================================

    /**
     * @notice Create a pool and assign both parties.
     * @dev  INV-3: partyA != partyB enforced here.
     *       INV-4: ltv capped at LTV_MAX (9999 bps).
     *
     * @param partyA      Side A address — must be whitelisted
     * @param partyB      Side B address — must be whitelisted, != partyA
     * @param ltv         LTV in basis points (1–9999). 0 = use 800 default.
     * @param deadlineSec Repayment window in seconds after pool opens. 0 = 30 days.
     * @return poolId     New pool ID
     */
    function createPool(
        address partyA,
        address partyB,
        uint256 ltv,
        uint256 deadlineSec
    )
        external
        onlyOwner
        whenNotPaused
        returns (uint256 poolId)
    {
        if (partyA == address(0) || partyB == address(0)) revert ZeroAddress();
        // Policy: vault owner can be on both sides of a pool.
        // Self-dealing restriction removed — owner has full discretion.
        // If partyA == partyB, this is an internal treasury credit line.
        // Original INV-3 removed for private vault. External parties still
        // subject to standard credit checks via whitelist.
        // Policy: owner is always approved — no whitelist entry needed.
        // Third parties must still be on the whitelist.
        if (partyA != owner && !globalWhitelist[partyA]) revert NotWhitelisted();
        if (partyB != owner && !globalWhitelist[partyB]) revert NotWhitelisted();

        uint256 _ltv = ltv == 0 ? LTV_DEFAULT : ltv;
        if (_ltv == 0 || _ltv > LTV_MAX) revert LTVOutOfRange();       // INV-4

        poolCount++;
        poolId = poolCount;

        Pool storage p = pools[poolId];
        p.poolId      = poolId;
        p.state       = PoolState.PENDING;
        p.ltv         = _ltv;
        // Policy: evergreen credit lines — deadline 0 means no expiry.
        // Owner sets explicit deadline for third parties, 0 for own lines.
        p.deadline    = deadlineSec; // 0 = evergreen (no expiry enforced)
        p.sideA.party = partyA;
        p.sideB.party = partyB;

        emit PoolCreated(poolId, msg.sender);
    }

    /**
     * @notice Seed one side of the pool with a WhaleVault minting lock.
     * @dev  INV-1: lockId 0 always rejected.
     *       INV-2: lockId cannot already be assigned to any pool.
     *       lockIdToPoolId is written AFTER all validation — not before.
     *       Pool opens automatically when both sides seeded.
     *
     * @param poolId  Pool to seed
     * @param side    0 = Side A, 1 = Side B
     * @param lockId  EWBWhaleVault minting lock ID (must be > 0)
     */
    function seedPool(uint256 poolId, uint8 side, uint256 lockId)
        external
        onlyOwner
        nonReentrant
        whenNotPaused
    {
        if (lockId == 0) revert ZeroLockId();                          // INV-1

        Pool storage p = pools[poolId];
        if (p.poolId == 0) revert PoolNotFound();
        if (p.state == PoolState.OPEN
         || p.state == PoolState.CLOSED
         || p.state == PoolState.DEFAULTED) revert PoolAlreadyActive();
        if (side > 1) revert InvalidSide();

        // Validate side not already seeded before any external call
        if (side == 0 && p.sideA.lockId != 0) revert SideAlreadySeeded();
        if (side == 1 && p.sideB.lockId != 0) revert SideAlreadySeeded();

        // INV-2: Prevent same lock used in multiple pools
        if (lockIdToPoolId[lockId] != 0) revert LockAlreadyInUse(lockId);

        // Read lock from WhaleVault
        (
            uint256[] memory tokenIds,
            ,
            uint256 faceValueUSD,
            ,
            ,
            bool active,

        ) = whaleVault.getMintingLock(lockId);

        if (!active) revert LockNotActive(lockId);

        // Verify every token in the lock is individually confirmed locked
        for (uint256 i = 0; i < tokenIds.length; i++) {
            if (!whaleVault.isMintingRightLocked(tokenIds[i]))
                revert NFTNotLocked(tokenIds[i]);
        }

        uint256 credit = faceValueUSD * p.ltv / PRECISION;

        // Write state only after all validation passes — INV-7 pattern
        lockIdToPoolId[lockId] = poolId;

        // SINGLE AUTHORITY: notify WhaleVault of the binding.
        // WhaleVault.lockPoolBinding becomes the canonical record.
        // This prevents unlockMintingRights() from deactivating an in-use lock.
        whaleVault.onSeed(lockId, poolId);

        if (side == 0) {
            p.sideA.lockId       = lockId;
            p.sideA.faceValueUSD = faceValueUSD;
            p.sideA.creditLimit  = credit;
        } else {
            p.sideB.lockId       = lockId;
            p.sideB.faceValueUSD = faceValueUSD;
            p.sideB.creditLimit  = credit;
        }

        emit PoolSideSeeded(poolId, side, lockId);

        // Transition to OPEN when both sides seeded
        if (p.sideA.lockId != 0 && p.sideB.lockId != 0) {
            p.state    = PoolState.OPEN;
            p.openedAt = block.timestamp;
            emit PoolOpened(poolId);
        }
    }

    // ============================================================
    // CREDIT DRAW & REPAY
    // ============================================================

    /**
     * @notice Draw internal credit against the opposing side's collateral.
     * @dev  Party A draws against Side B's lock; Party B against Side A's.
     *       INV-5: amount cannot exceed available credit on opposing side.
     *
     * @param poolId Pool to draw from
     * @param amount Credit units to draw (6 decimals, same scale as faceValueUSD)
     */
    function drawCredit(uint256 poolId, uint256 amount)
        external
        onlyWhitelisted
        nonReentrant
        whenNotPaused
    {
        if (amount == 0) revert ZeroAmount();

        Pool storage p = pools[poolId];
        if (p.state != PoolState.OPEN) revert PoolNotOpen();

        bool isPartyA = (msg.sender == p.sideA.party);
        bool isPartyB = (msg.sender == p.sideB.party);
        if (!isPartyA && !isPartyB) revert NotPoolParty();

        // C-1 FIX: Boolean dispatch fails under identity collapse (partyA == partyB).
        // When both predicates are true, isPartyA always wins — Side A collateral
        // is permanently unencumberable, half the credit capacity is dead.
        //
        // Fix: split on identity equality first.
        // Normal case (disjoint parties): identity determines which side is collateral.
        // Degenerate case (self-dealing, A == B): allocation is state-driven —
        // consume whichever side has remaining capacity. This is deterministic,
        // caller-independent, and preserves full credit access without API changes.

        if (p.sideA.party != p.sideB.party) {
            // ── Normal case: disjoint parties ──────────────────────────────
            if (isPartyA) {
                // Party A borrows against Side B collateral
                uint256 available = p.sideB.creditLimit - p.sideB.drawnCredit;
                if (amount > available) revert CreditExceedsLTV();
                p.sideB.drawnCredit += amount;
                if (p.sideB.drawnAt == 0) p.sideB.drawnAt = block.timestamp;
                emit CreditDrawn(poolId, 1, amount);
            } else {
                // Party B borrows against Side A collateral
                uint256 available = p.sideA.creditLimit - p.sideA.drawnCredit;
                if (amount > available) revert CreditExceedsLTV();
                p.sideA.drawnCredit += amount;
                if (p.sideA.drawnAt == 0) p.sideA.drawnAt = block.timestamp;
                emit CreditDrawn(poolId, 0, amount);
            }
        } else {
            // ── Degenerate case: self-dealing pool (partyA == partyB) ──────
            // Both sides are logically equivalent. Allocate against whichever
            // side has remaining capacity — fixed order (A first) ensures
            // deterministic behaviour with no caller-controlled selection.
            uint256 availableA = p.sideA.creditLimit - p.sideA.drawnCredit;
            uint256 availableB = p.sideB.creditLimit - p.sideB.drawnCredit;
            if (availableA >= amount) {
                p.sideA.drawnCredit += amount;
                if (p.sideA.drawnAt == 0) p.sideA.drawnAt = block.timestamp;
                emit CreditDrawn(poolId, 0, amount);
            } else if (availableB >= amount) {
                p.sideB.drawnCredit += amount;
                if (p.sideB.drawnAt == 0) p.sideB.drawnAt = block.timestamp;
                emit CreditDrawn(poolId, 1, amount);
            } else {
                // Neither side alone can cover — revert. No split draws.
                revert CreditExceedsLTV();
            }
        }
    }

    /**
     * @notice Multisig confirms repayment for one side.
     * @dev  If drawnCredit > 0: records repayment + interest accrued.
     *       Interest amount is added to totalInterestAccrued (informational).
     *       Actual USDC must be deposited separately via depositInterest().
     *       If drawnCredit == 0: records a waive (distinct event).
     *       Both paths mark the side repaid so the pool can close.
     *       When both sides repaid/waived, emits LockPendingRelease
     *       for each lockId — multisig MUST call WhaleVault separately.
     *
     * @param poolId Pool to repay
     * @param side   0 = Side A's obligation, 1 = Side B's obligation
     */
    function repayCredit(uint256 poolId, uint8 side)
        external
        onlyOwner
        nonReentrant
    {
        Pool storage p = pools[poolId];
        if (p.state != PoolState.OPEN) revert PoolNotOpen();
        if (side > 1) revert InvalidSide();

        PoolSide storage ps = side == 0 ? p.sideA : p.sideB;
        if (ps.repaid) revert SideAlreadyRepaid();

        if (ps.drawnCredit > 0) {
            uint256 interest = _calcInterest(ps.drawnCredit, ps.drawnAt);

            // --- INTEREST SWEEP: record accrued interest for this repayment ---
            // Interest is tracked here. Multisig deposits the actual USDC
            // via depositInterest() and then calls sweepInterestToRouter().
            totalInterestAccrued += interest;
            // -------------------------------------------------------------------

            emit CreditRepaid(poolId, side, ps.drawnCredit, interest);
            ps.drawnCredit = 0;
            ps.drawnAt     = 0;  // clear clock so interest reads as 0 post-repay
        } else {
            emit CreditWaived(poolId, side);
        }

        ps.repaid = true;

        if (p.sideA.repaid && p.sideB.repaid) {
            _closePool(p);
        }
    }

    // ============================================================
    // INTEREST SWEEP — TREASURY INCOME (new)
    // ============================================================

    /**
     * @notice Multisig deposits the interest portion of a repayment into
     *         this contract so it can be swept on-chain to the revenue router.
     *
     * @dev    Called AFTER repayCredit(). The multisig has received USDC
     *         off-chain from the borrower. The interest slice is deposited
     *         here and tracked in pendingInterest[token].
     *
     *         CEI: state written before external transferFrom call.
     *
     * @param token  Token address (USDC mainnet: 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48)
     * @param amount Interest amount in token decimals (USDC = 6 dec)
     * @param poolId Pool ID this interest relates to (for audit trail)
     * @param side   Side that repaid (0 or 1)
     */
    function depositInterest(
        address token,
        uint256 amount,
        uint256 poolId,
        uint8   side
    )
        external
        onlyOwner
        nonReentrant
    {
        if (token  == address(0)) revert ZeroAddress();
        if (amount == 0)          revert ZeroAmount();

        // CEI: write state before external call — INV-9
        pendingInterest[token] += amount;

        // Pull USDC from multisig wallet into this contract
        bool ok = IERC20Sweep(token).transferFrom(msg.sender, address(this), amount);
        require(ok, "EWBPrivatePool: interest deposit transfer failed");

        emit InterestDeposited(token, amount, poolId, side);
    }

    /**
     * @notice Sweep all accumulated interest for a given token to the
     *         EWBRevenueRouter, which records it as private pool income
     *         and forwards to the SPV treasury.
     *
     * @dev    INV-8: only moves tokens actually held by this contract.
     *         Calls routePrivatePoolInterest() on the router — that function
     *         must be added to EWBRevenueRouter (see amendment note below).
     *         Reverts if router not set, nothing pending, or balance too low.
     *
     *         CEI: state cleared before external transfer.
     *
     * @param token Token to sweep (must have pendingInterest > 0)
     */
    function sweepInterestToRouter(address token)
        external
        onlyOwner
        nonReentrant
    {
        if (revenueRouter == address(0)) revert RouterNotSet();
        if (token == address(0))         revert ZeroAddress();

        uint256 amount = pendingInterest[token];
        if (amount == 0) revert NothingToSweep();

        // INV-8: verify this contract actually holds the tokens
        uint256 bal = IERC20Sweep(token).balanceOf(address(this));
        if (bal < amount) revert InsufficientContractBalance();

        // CEI: clear pending before external call — INV-9
        pendingInterest[token]    = 0;
        totalInterestSwept[token] += amount;

        // Transfer to router
        bool ok = IERC20Sweep(token).transfer(revenueRouter, amount);
        require(ok, "EWBPrivatePool: sweep transfer failed");

        // Notify router to record the income stream
        IEWBRevenueRouter(revenueRouter).routePrivatePoolInterest(token, amount);

        emit InterestSwept(token, amount, revenueRouter);
    }

    /**
     * @notice Preview pending interest for a given token without sweeping.
     * @param token Token address to check
     * @return pending Amount awaiting sweep (token decimals)
     * @return swept   Lifetime amount swept to router (token decimals)
     */
    function interestSweepStatus(address token)
        external view
        returns (uint256 pending, uint256 swept)
    {
        return (pendingInterest[token], totalInterestSwept[token]);
    }

    // ============================================================
    // DEFAULT & COLLATERAL CLAIM
    // ============================================================

    /**
     * @notice Mark a side as defaulted after the repayment deadline.
     * @dev  INV-6: Requires drawnCredit > 0 — can't default on zero draw.
     *       Requires repaid == false.
     *
     * @param poolId Pool ID
     * @param side   0 = Side A defaulted, 1 = Side B defaulted
     */
    function markDefault(uint256 poolId, uint8 side)
        external
        onlyOwner
    {
        Pool storage p = pools[poolId];
        if (p.state != PoolState.OPEN) revert PoolNotOpen();
        if (side > 1) revert InvalidSide();
        // FIX-5: Evergreen pools have deadline = 0, meaning no expiry enforced.
        // Original check: block.timestamp < openedAt + 0 => always false after open,
        // allowing immediate default on evergreen pools — wrong behaviour.
        // Fix: only enforce deadline check when deadline > 0.
        if (p.deadline > 0) {
            if (block.timestamp < p.openedAt + p.deadline) revert DeadlineNotReached();
        }

        PoolSide storage ps = side == 0 ? p.sideA : p.sideB;
        if (ps.defaulted)    revert AlreadyDefaulted();
        if (ps.repaid)       revert SideAlreadyRepaid();
        if (ps.drawnCredit == 0) revert NoDrawToDefault();              // INV-6

        ps.defaulted = true;
        p.state      = PoolState.DEFAULTED;

        emit PoolDefaultMarked(poolId, side);
    }

    /**
     * @notice Record collateral claim after default.
     * @dev  Clears the defaulted side's lockId from registry.
     *       Emits LockPendingRelease — multisig MUST then call
     *       EWBWhaleVault.unlockMintingRights(defaultedLockId) directly.
     *
     *       The non-defaulted side's lock is also released via
     *       LockPendingRelease so the pool is fully unwound.
     *
     * @param poolId        Pool ID
     * @param defaultedSide Side that defaulted (0 or 1)
     */
    function claimCollateral(uint256 poolId, uint8 defaultedSide)
        external
        onlyOwner
        nonReentrant
    {
        Pool storage p = pools[poolId];
        if (p.state != PoolState.DEFAULTED) revert NotDefaulted();
        if (defaultedSide > 1) revert InvalidSide();

        PoolSide storage ds = defaultedSide == 0 ? p.sideA : p.sideB;
        PoolSide storage ns = defaultedSide == 0 ? p.sideB : p.sideA;

        if (!ds.defaulted) revert NotDefaulted();
        require(ds.lockId != 0, "Collateral already claimed");

        uint256 defaultedLockId    = ds.lockId;
        uint256 nonDefaultedLockId = ns.lockId;
        uint8   claimantSide       = defaultedSide == 0 ? 1 : 0;

        // Clear lock registry — emit IDs BEFORE zeroing so they are visible
        emit LockPendingRelease(poolId, defaultedLockId);
        if (nonDefaultedLockId != 0) {
            emit LockPendingRelease(poolId, nonDefaultedLockId);
        }

        ds.lockId = 0;
        ns.lockId = 0;
        // SINGLE AUTHORITY: release bindings in WhaleVault
        whaleVault.onClaim(defaultedLockId);
        lockIdToPoolId[defaultedLockId] = 0;
        // H-2 FIX: only clear non-defaulted side if it has a real lockId.
        // Avoids writing lockIdToPoolId[0] = 0 which pollutes the zero sentinel.
        if (nonDefaultedLockId != 0) {
            whaleVault.onClaim(nonDefaultedLockId);
            lockIdToPoolId[nonDefaultedLockId] = 0;
        }

        p.state = PoolState.CLOSED;

        emit CollateralClaimRecorded(poolId, claimantSide, defaultedLockId);
        emit PoolClosed(poolId);
    }

    // ============================================================
    // VIEWS
    // ============================================================

    function getPool(uint256 poolId)
        external view
        returns (
            PoolState state,
            uint256   ltv,
            uint256   openedAt,
            uint256   deadlineAt,
            address   partyA,
            uint256   sideA_lockId,
            uint256   sideA_creditLimit,
            uint256   sideA_drawnCredit,
            uint256   sideA_accruedInterest,
            bool      sideA_repaid,
            bool      sideA_defaulted,
            address   partyB,
            uint256   sideB_lockId,
            uint256   sideB_creditLimit,
            uint256   sideB_drawnCredit,
            uint256   sideB_accruedInterest,
            bool      sideB_repaid,
            bool      sideB_defaulted
        )
    {
        Pool storage p = pools[poolId];
        if (p.poolId == 0) revert PoolNotFound();

        return (
            p.state,
            p.ltv,
            p.openedAt,
            p.openedAt > 0 ? p.openedAt + p.deadline : 0,
            p.sideA.party,
            p.sideA.lockId,
            p.sideA.creditLimit,
            p.sideA.drawnCredit,
            _calcInterest(p.sideA.drawnCredit, p.sideA.drawnAt),
            p.sideA.repaid,
            p.sideA.defaulted,
            p.sideB.party,
            p.sideB.lockId,
            p.sideB.creditLimit,
            p.sideB.drawnCredit,
            _calcInterest(p.sideB.drawnCredit, p.sideB.drawnAt),
            p.sideB.repaid,
            p.sideB.defaulted
        );
    }

    function getTotalDue(uint256 poolId, uint8 side)
        external view
        returns (uint256 principal, uint256 interest, uint256 totalDue)
    {
        Pool storage p = pools[poolId];
        if (p.poolId == 0) revert PoolNotFound();
        PoolSide storage ps = side == 0 ? p.sideA : p.sideB;
        principal = ps.drawnCredit;
        interest  = _calcInterest(ps.drawnCredit, ps.drawnAt);
        totalDue  = principal + interest;
    }

    function isDeadlinePassed(uint256 poolId) external view returns (bool) {
        Pool storage p = pools[poolId];
        if (p.poolId == 0 || p.openedAt == 0) return false;
        return block.timestamp >= p.openedAt + p.deadline;
    }

    // ============================================================
    // ADMIN
    // ============================================================

    function pause() external onlyEmergency {
        pausedAt = block.timestamp;
        _pause();
    }

    function unpause() external onlyEmergency { _unpause(); }

    function forceUnpause() external onlyOwner {
        require(paused(), "Not paused");
        if (block.timestamp < pausedAt + MAX_PAUSE_DURATION)
            revert MaxPauseNotReached();
        _unpause();
        emit ForcedUnpause(msg.sender, block.timestamp);
    }

    // ============================================================
    // INTERNAL
    // ============================================================

    /**
     * @dev Close pool on full repayment.
     *      Emits LockPendingRelease for each active lock BEFORE zeroing.
     *      Multisig must call EWBWhaleVault.unlockMintingRights() for each.
     */
    function _closePool(Pool storage p) internal {
        p.state = PoolState.CLOSED;

        if (p.sideA.lockId != 0) {
            emit LockPendingRelease(p.poolId, p.sideA.lockId);
            // SINGLE AUTHORITY: release binding in WhaleVault first
            whaleVault.onClose(p.sideA.lockId);
            lockIdToPoolId[p.sideA.lockId] = 0;
            p.sideA.lockId = 0;
        }
        if (p.sideB.lockId != 0) {
            emit LockPendingRelease(p.poolId, p.sideB.lockId);
            // SINGLE AUTHORITY: release binding in WhaleVault first
            whaleVault.onClose(p.sideB.lockId);
            lockIdToPoolId[p.sideB.lockId] = 0;
            p.sideB.lockId = 0;
        }

        emit PoolClosed(p.poolId);
    }

    /**
     * @dev Simple interest at 5% pa. Returns 0 if clock is cleared (post-repay).
     */
    function _calcInterest(uint256 principal, uint256 originatedAt)
        internal view returns (uint256)
    {
        if (originatedAt == 0 || principal == 0) return 0;
        uint256 elapsed = block.timestamp - originatedAt;
        // L-8 NOTE: If drawn and repaid in the same block, elapsed = 0 and interest = 0.
        // This is acceptable — same-block arbitrage is economically irrational at 5% pa.
        return principal * INTEREST_RATE_BPS * elapsed / PRECISION / SECONDS_PER_YEAR;
    }
}

contracts/EWBRealWorldAsset.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

/**
 * @title EWBRealWorldAsset
 * @author Wayne Fyffe — Exposed Walls (EWB)
 * @notice On-chain registry anchoring the physical Banksy mural
 *         "Gorilla in a Pink Mask" (Bristol, UK, circa 2001)
 *         as a verified Real World Asset (RWA)
 * @dev TECH1 GODMODE FINAL v8 — OpenZeppelin Audit Standard
 *
 * ================================================================
 * PURPOSE
 * ================================================================
 *
 * This contract creates a legally and cryptographically verifiable
 * bridge between the physical asset and the EWB token ecosystem.
 *
 * WHY THIS MATTERS FOR AUDITORS:
 *
 * Without this contract, the $211M ecosystem value rests on
 * NFT floor prices and trait valuations — both of which auditors
 * classify as "subjective pricing models."
 *
 * With this contract, the system has:
 *   1. A verified professional appraisal ($10M–$25M FMV)
 *   2. Legal ownership chain on-chain
 *   3. IPFS-pinned documents (appraisal, provenance, insurance)
 *   4. SPV treasury address as verified custodian
 *   5. Trademark registration anchored
 *
 * This moves the collateral basis from "NFT floor price" to
 * "verified physical asset with professional appraisal" —
 * the category institutional auditors accept.
 *
 * ================================================================
 * PHYSICAL ASSET DETAILS
 * ================================================================
 *
 * Asset:       Banksy "Gorilla in a Pink Mask"
 * Location:    Bristol, UK (original site)
 * Date:        Circa 2001
 * Dimensions:  Approx 3.2ft × 5.6ft (brick mural)
 * Medium:      Spray paint on brick wall
 *
 * Appraiser:   Dr. Lori Verderame Ph.D.
 * Appraisal:   February 28, 2026
 * FMV Low:     $10,000,000 USD
 * FMV Mid:     $17,500,000 USD
 * FMV High:    $25,000,000 USD
 *
 * Legal Owner: Wayne Fyffe
 * SPV:         0xc82A59594560A3010F336ebe2e9CC4794DCD46cf
 * Trademark:   UK00003897277 — Wayne Fyffe — Class 16 — to 2033
 *
 * ================================================================
 * WHAT IS STORED ON-CHAIN
 * ================================================================
 *
 * All document hashes are IPFS CIDs (content-addressed).
 * Anyone can verify: IPFS CID → document → matches on-chain hash.
 *
 * Documents anchored:
 *   - Professional appraisal (Dr. Lori Verderame, Feb 2026)
 *   - Provenance / ownership certificate
 *   - Insurance certificate
 *   - Trademark registration certificate
 *   - Legal ownership declaration (irrevocable)
 *
 * ================================================================
 * GOVERNANCE
 * ================================================================
 *
 * Once the asset record is finalised via finalise():
 *   - Core asset data becomes IMMUTABLE
 *   - No one can change FMV, appraiser, or ownership
 *   - Documents can be added but not removed
 *   - This is the permanent on-chain record
 *
 * ================================================================
 * AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
 * ================================================================
 */

contract EWBRealWorldAsset {

    // ============================================================
    // ERRORS
    // ============================================================

    error OnlyOwner();
    error AlreadyFinalised();
    error NotFinalised();
    error ZeroAddress();
    error EmptyString();
    error EmptyHash();
    error DocumentAlreadyExists(string docType);
    error InvalidFMV();

    // ============================================================
    // ASSET CONSTANTS — set at deploy, immutable after finalise()
    // ============================================================

    /// @notice EWB ERC-721 contract linked to this physical asset
    address public constant EWB_NFT =
        0x0c06d6A17eb208A9BC7Bd698Eb6f22379209e3A4;

    /// @notice SPV Treasury — legal custodian on-chain
    address public constant SPV_TREASURY =
        0xc82A59594560A3010F336ebe2e9CC4794DCD46cf;

    /// @notice UK Trademark number
    string  public constant TRADEMARK_NUMBER = "UK00003897277";

    /// @notice Trademark class
    uint256 public constant TRADEMARK_CLASS  = 16;

    /// @notice Trademark valid until (year)
    uint256 public constant TRADEMARK_EXPIRY = 2033;

    // ============================================================
    // ASSET RECORD — mutable until finalise()
    // ============================================================

    struct AssetRecord {
        // Physical asset
        string  assetName;          // "Gorilla in a Pink Mask"
        string  assetArtist;        // "Banksy"
        string  assetLocation;      // "Bristol, UK"
        uint256 assetYear;          // 2001
        string  assetMedium;        // "Spray paint on brick wall"
        string  assetDimensions;    // "3.2ft x 5.6ft"

        // Appraisal
        string  appraiserName;      // "Dr. Lori Verderame Ph.D."
        uint256 appraisalDate;      // Unix timestamp
        uint256 fmvLow;             // $10,000,000 USD (6 dec)
        uint256 fmvMid;             // $17,500,000 USD (6 dec)
        uint256 fmvHigh;            // $25,000,000 USD (6 dec)

        // Legal ownership
        string  legalOwner;         // "Wayne Fyffe"
        address ownerAddress;       // Safe multisig address
        uint256 ownershipTransferBlock; // Block when transferred to SPV

        // Status
        bool    finalised;          // Once true — immutable
        uint256 finalisedAt;
    }

    AssetRecord public asset;

    // ============================================================
    // DOCUMENT REGISTRY
    // ============================================================

    struct Document {
        string  docType;        // "appraisal" | "provenance" | "insurance" | "trademark" | "declaration"
        string  ipfsCID;        // IPFS content identifier
        string  description;
        uint256 anchoredAt;     // Block timestamp
        address anchoredBy;     // Who anchored this document
    }

    mapping(string => Document) public documents;  // docType => Document
    string[] public documentTypes;                  // Ordered list
    mapping(string => bool) public documentExists;

    // ============================================================
    // GOVERNANCE
    // ============================================================

    address public owner; // Safe multisig — set at deploy

    // ============================================================
    // EVENTS
    // ============================================================

    event AssetRecordCreated(
        string  assetName,
        string  artist,
        uint256 fmvLow,
        uint256 fmvHigh,
        uint256 timestamp
    );
    event AssetFinalised(
        string  assetName,
        uint256 fmvMid,
        address ownerAddress,
        uint256 timestamp
    );
    event DocumentAnchored(
        string  indexed docType,
        string  ipfsCID,
        string  description,
        uint256 timestamp
    );
    event DocumentUpdated(
        string  indexed docType,
        string  oldCID,
        string  newCID,
        uint256 timestamp
    );
    event FMVUpdated(
        uint256 oldLow, uint256 oldHigh,
        uint256 newLow, uint256 newHigh,
        uint256 timestamp
    );

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    modifier notFinalised() {
        if (asset.finalised) revert AlreadyFinalised();
        _;
    }

    modifier whenFinalised() {
        if (!asset.finalised) revert NotFinalised();
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    /**
     * @notice Deploy with Safe multisig as owner
     * @dev Immediately creates the initial asset record.
     *      Call anchorDocument() for each supporting document.
     *      Call finalise() to make the record immutable.
     *
     * @param _safeMultisig Safe 2-of-3 multisig — primary governance
     */
    constructor(address _safeMultisig) {
        if (_safeMultisig == address(0)) revert ZeroAddress();
        owner = _safeMultisig;

        // Initialise asset record with known details
        asset.assetName          = "Gorilla in a Pink Mask";
        asset.assetArtist        = "Banksy";
        asset.assetLocation      = "Bristol, UK";
        asset.assetYear          = 2001;
        asset.assetMedium        = "Spray paint on brick wall";
        asset.assetDimensions    = "3.2ft x 5.6ft (approx)";
        asset.appraiserName      = "Dr. Lori Verderame Ph.D.";
        asset.appraisalDate      = 1740700800; // Feb 28 2026 UTC
        asset.fmvLow             = 10_000_000e6; // $10M in 6 dec
        asset.fmvMid             = 17_500_000e6; // $17.5M in 6 dec
        asset.fmvHigh            = 25_000_000e6; // $25M in 6 dec
        asset.legalOwner         = "Wayne Fyffe";
        asset.ownerAddress       = _safeMultisig;
        asset.ownershipTransferBlock = 24345896; // Block when transferred to SPV
        asset.finalised          = false;

        emit AssetRecordCreated(
            asset.assetName,
            asset.assetArtist,
            asset.fmvLow,
            asset.fmvHigh,
            block.timestamp
        );
    }

    // ============================================================
    // DOCUMENT ANCHORING
    // ============================================================

    /**
     * @notice Anchor a document to this RWA record via IPFS CID
     * @dev Documents are content-addressed — IPFS CID is the proof.
     *      Anyone can verify: fetch CID from IPFS, hash matches on-chain.
     *      Can be called before or after finalise().
     *      After finalise(): documents can be added but CIDs cannot change.
     *
     * Document types:
     *   "appraisal"    — Professional valuation by Dr. Lori Verderame
     *   "provenance"   — Ownership and acquisition history
     *   "insurance"    — Insurance certificate and coverage
     *   "trademark"    — UK00003897277 registration certificate
     *   "declaration"  — Irrevocable legal ownership declaration
     *   "payment"      — Lloyds Bank payment confirmation (provenance)
     *
     * @param docType    Category identifier
     * @param ipfsCID    IPFS content identifier (starts with "Qm" or "bafy")
     * @param description Human-readable description of the document
     */
    function anchorDocument(
        string calldata docType,
        string calldata ipfsCID,
        string calldata description
    )
        external
        onlyOwner
    {
        if (bytes(docType).length    == 0) revert EmptyString();
        if (bytes(ipfsCID).length    == 0) revert EmptyHash();
        if (bytes(description).length == 0) revert EmptyString();

        if (documentExists[docType]) {
            // After finalise() — cannot change existing CID
            if (asset.finalised) revert AlreadyFinalised();

            // Before finalise() — update allowed, emit UpdatedEvent
            string memory oldCID = documents[docType].ipfsCID;
            documents[docType].ipfsCID      = ipfsCID;
            documents[docType].description  = description;
            documents[docType].anchoredAt   = block.timestamp;
            documents[docType].anchoredBy   = msg.sender;
            emit DocumentUpdated(docType, oldCID, ipfsCID, block.timestamp);
        } else {
            // New document
            documents[docType] = Document({
                docType:     docType,
                ipfsCID:     ipfsCID,
                description: description,
                anchoredAt:  block.timestamp,
                anchoredBy:  msg.sender
            });
            documentTypes.push(docType);
            documentExists[docType] = true;
            emit DocumentAnchored(docType, ipfsCID, description, block.timestamp);
        }
    }

    // ============================================================
    // PRE-FINALISE UPDATES
    // ============================================================

    /**
     * @notice Update FMV range before finalisation
     * @dev Once finalised, FMV is immutable.
     *      Use if appraiser provides updated valuation.
     */
    function updateFMV(
        uint256 newLow,
        uint256 newMid,
        uint256 newHigh
    )
        external
        onlyOwner
        notFinalised
    {
        if (newLow == 0 || newMid < newLow || newHigh < newMid)
            revert InvalidFMV();

        emit FMVUpdated(
            asset.fmvLow, asset.fmvHigh,
            newLow, newHigh,
            block.timestamp
        );

        asset.fmvLow  = newLow;
        asset.fmvMid  = newMid;
        asset.fmvHigh = newHigh;
    }

    // ============================================================
    // FINALISE — makes record immutable
    // ============================================================

    /**
     * @notice Finalise the RWA record — makes core data immutable
     * @dev After finalisation:
     *      - Asset name, artist, location, year, medium cannot change
     *      - FMV range cannot change
     *      - Legal owner cannot change
     *      - Existing document CIDs cannot change
     *      - New documents CAN still be added
     *
     *      Recommended: anchor all key documents before finalising.
     *      Required documents before finalising:
     *        - "appraisal" — must be anchored
     *        - "provenance" — must be anchored
     *        - "declaration" — must be anchored
     */
    function finalise() external onlyOwner notFinalised {
        require(documentExists["appraisal"],  "Appraisal document required");
        require(documentExists["provenance"], "Provenance document required");
        require(documentExists["declaration"],"Declaration document required");

        asset.finalised   = true;
        asset.finalisedAt = block.timestamp;

        emit AssetFinalised(
            asset.assetName,
            asset.fmvMid,
            asset.ownerAddress,
            block.timestamp
        );
    }

    // ============================================================
    // VIEWS
    // ============================================================

    /**
     * @notice Get full asset record
     */
    function getAssetRecord() external view returns (AssetRecord memory) {
        return asset;
    }

    /**
     * @notice Get a specific document by type
     */
    function getDocument(string calldata docType)
        external view returns (Document memory)
    {
        return documents[docType];
    }

    /**
     * @notice Get all anchored document types
     */
    function getAllDocumentTypes()
        external view returns (string[] memory)
    {
        return documentTypes;
    }

    /**
     * @notice Get document count
     */
    function getDocumentCount() external view returns (uint256) {
        return documentTypes.length;
    }

    /**
     * @notice Verify this contract represents the given NFT contract
     */
    function isLinkedTo(address nftContract)
        external pure returns (bool)
    {
        return nftContract == EWB_NFT;
    }

    /**
     * @notice Get FMV range in USD (6 decimals)
     */
    function getFMVRange() external view returns (
        uint256 low,
        uint256 mid,
        uint256 high,
        string memory appraiser,
        uint256 appraisalDate
    ) {
        return (
            asset.fmvLow,
            asset.fmvMid,
            asset.fmvHigh,
            asset.appraiserName,
            asset.appraisalDate
        );
    }

    /**
     * @notice Check if a document type has been anchored
     */
    function hasDocument(string calldata docType)
        external view returns (bool)
    {
        return documentExists[docType];
    }

    /**
     * @notice Summary for institutional review
     */
    function getSummary() external view returns (
        string memory  name,
        string memory  artist,
        uint256        fmvLow,
        uint256        fmvHigh,
        bool           finalised,
        uint256        documentCount,
        address        spvTreasury,
        string memory  trademark
    ) {
        return (
            asset.assetName,
            asset.assetArtist,
            asset.fmvLow,
            asset.fmvHigh,
            asset.finalised,
            documentTypes.length,
            SPV_TREASURY,
            TRADEMARK_NUMBER
        );
    }
}

contracts/EWBRevenueRouter.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19; // M-05 fix: exact version, not caret

/**
 * @title EWB Revenue Router
 * @notice Aggregates and distributes all three income streams
 *         to the owner wallet and optionally to ERC-6551 TBAs
 *
 * ================================================================
 * THREE INCOME STREAMS
 * ================================================================
 *
 * Stream 1 — LP Fees (Uniswap V3 EWB/WETH pool)
 *   Annual estimate: ~$160,823 at current TVL
 *   Route: Uniswap V3 position fees → this router → owner
 *
 * Stream 2 — stETH Yield (Aave v3 long leg)
 *   Annual estimate: ~$7,340 at 100 ETH deployed
 *   Route: Aave aStETH rebase → harvest → this router → owner
 *
 * Stream 3 — dYdX Funding Rate (delta-neutral short leg)
 *   Annual estimate: ~$16,776 at 8% funding rate
 *   Route: dYdX account → manual claim → this router → owner
 *
 * Total estimated annual income: ~$184,939
 *
 * ================================================================
 * ROUTING RULES
 * ================================================================
 *
 * Treasury tokens (8,632 unminted): ALL income → owner wallet
 * TBA-registered tokens: income can split to individual TBAs
 * Default: 100% to owner until TBAs are registered
 *
 * AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
 * ================================================================
 */

// FIX: Added ReentrancyGuard to protect token transfer functions from reentrancy
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount)
        external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20Router {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IERC6551Registry {
    function account(
        address implementation,
        uint256 chainId,
        address tokenContract,
        uint256 tokenId,
        uint256 salt
    ) external view returns (address);
}

// FIX C-1: SafeCall library — handles non-standard ERC-20 tokens (USDT-style bool-less returns)
library SafeCall {
    function safeTransfer(address token, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSignature("transfer(address,uint256)", to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))),
            "SafeCall: transfer failed");
    }
    function safeTransferFrom(address token, address from, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", from, to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))),
            "SafeCall: transferFrom failed");
    }
}

contract EWBRevenueRouter is ReentrancyGuard {

    // ================================================================
    // FIX-H4: EXPLICIT VALUE FLOW PARTITIONING
    // All value flows fall into exactly 3 buckets:
    //   Bucket 1 — BORROWERS:  openLoan() -> borrower wallet
    //   Bucket 2 — PROVIDERS:  distributeYield() -> NFT holders
    //                          withdrawLender() -> LP positions
    //   Bucket 3 — TREASURY:   routeLPFees() -> safeMultisig
    //                          routeDyDxIncome() -> safeMultisig
    //                          harvestYield() -> safeMultisig
    // No value flow exists outside these 3 buckets.
    // ================================================================

    // ============================================================
    // CONSTANTS
    // ============================================================

    address public constant EWB_CONTRACT =
        0x0c06d6A17eb208A9BC7Bd698Eb6f22379209e3A4;
    address public constant SPV_TREASURY =
        0xc82A59594560A3010F336ebe2e9CC4794DCD46cf;

    // ERC-6551 Registry (mainnet)
    address public constant TBA_REGISTRY =
        0x000000006551c19487814612e58FE06813775758;

    // Income stream sources
    uint8 public constant STREAM_LP_FEES      = 0; // Uniswap V3
    uint8 public constant STREAM_STETH        = 1; // Aave v3
    uint8 public constant STREAM_DYDX         = 2; // dYdX funding
    uint8 public constant STREAM_PRIVATE_POOL = 3; // Private pool interest
    uint8 public constant STREAM_MINTING_VAULT = 4; // MintingRightsVault interest

    // ============================================================
    // STATE
    // ============================================================

    address public owner;
    bool    public paused;

    // Income tracking per stream
    mapping(uint8 => uint256) public totalReceived;
    mapping(uint8 => uint256) public totalDistributed;

    // TBA registration — token ID => registered TBA address
    mapping(uint256 => address) public tokenTBA;
    mapping(uint256 => uint256) public tbaSplitBps; // basis points to TBA

    // Revenue history
    struct IncomeEvent {
        uint8   stream;
        uint256 amount;
        address recipient;
        uint256 timestamp;
    }
    IncomeEvent[] public incomeHistory;

    // Annual income estimates (informational — updated by owner)
    uint256 public estimatedAnnualLPFees      = 160_823e6; // USDC 6dec
    uint256 public estimatedAnnualStETH       =   7_340e6;
    uint256 public estimatedAnnualDyDx        =  16_776e6;
    uint256 public estimatedAnnualPrivatePool =       0; // set after pool utilisation is known

    // Private pool interest — authorised caller

    // Delta vault — authorised to auto-record stETH yield
    address public immutable deltaVault;

    // Minting vault — authorised to route lending interest
    address public immutable mintingVault;

    // ============================================================
    // EVENTS
    // ============================================================

    event IncomeReceived(uint8 indexed stream, uint256 amount, address token);
    event IncomeDistributed(uint8 indexed stream, uint256 ownerAmount,
        uint256 tbaAmount, address recipient);
    event TBARegistered(uint256 indexed tokenId, address tba, uint256 splitBps);
    event EstimatesUpdated(uint256 lp, uint256 steth, uint256 dydx);
    event DeltaVaultSet(address indexed vault);
    event MintingVaultSet(address indexed vault);
    event MintingVaultInterestRouted(address indexed token, uint256 amount);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyOwner() { require(msg.sender == owner, "Only owner"); _; }
    modifier notPaused() { require(!paused, "Paused"); _; }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    // ============================================================
    // OWNER — HARDCODED TO BALLET WALLET
    // All income from all 5 streams routes to this address only.
    // Cannot be changed post-deploy — immutable by design.
    // Replace BALLET_WALLET_ADDRESS with Wayne's actual 0x address
    // before deploying. This is the single destination for all funds.
    // ============================================================

    address public constant BALLET_WALLET =
        address(0xc82A59594560A3010F336ebe2e9CC4794DCD46cf);

    constructor(address _deltaVault, address _mintingVault) {
        require(_deltaVault   != address(0), "Zero deltaVault");
        require(_mintingVault != address(0), "Zero mintingVault");
        owner        = BALLET_WALLET;
        deltaVault   = _deltaVault;
        mintingVault = _mintingVault;
    }

    // ============================================================
    // STREAM 1 — LP FEES (called after collecting Uniswap V3 fees)
    // ============================================================

    /**
     * @notice Route collected LP fees to owner
     * @param token Fee token address (WETH or USDC)
     * @param amount Amount collected from Uniswap V3 position
     */
    function routeLPFees(
        address token,
        uint256 amount
    ) external onlyOwner nonReentrant notPaused {
        require(amount > 0, "No fees to route");
        totalReceived[STREAM_LP_FEES] += amount;
        // FIX H-2: Pull funds to this contract first, then split
        require(
            IERC20Router(token).transferFrom(msg.sender, address(this), amount),
            "LP fee transfer failed"
        );
        _splitAndDistribute(token, amount, STREAM_LP_FEES);
    }

    // ============================================================
    // STREAM 2 — stETH YIELD (called after harvesting from vault)
    // ============================================================

    /**
     * @notice Route harvested stETH yield to owner
     * @dev Called after EWBDeltaNeutralVault.harvestYield()
     *      stETH already transferred to owner by vault — this
     *      records the income event for accounting purposes
     * @param amount Amount harvested in stETH (18 decimals)
     */
    function recordStETHYield(uint256 amount) external onlyOwner {
        require(amount > 0, "No yield to record");

        totalReceived[STREAM_STETH] += amount;
        totalDistributed[STREAM_STETH] += amount;

        incomeHistory.push(IncomeEvent({
            stream:    STREAM_STETH,
            amount:    amount,
            recipient: owner,
            timestamp: block.timestamp
        }));

        emit IncomeReceived(STREAM_STETH, amount, address(0));
        emit IncomeDistributed(STREAM_STETH, amount, 0, owner);
    }

    /**
     * @notice Auto-record stETH yield — called directly by EWBDeltaNeutralVault
     * @dev Vault calls this immediately after transferring stETH to safeMultisig,
     *      so income is recorded on-chain without a separate manual multisig call.
     *      Caller must be the registered deltaVault address.
     * @param amount Amount harvested in stETH (18 decimals)
     */
    function recordStETHYieldAuto(uint256 amount) external {
        require(msg.sender == deltaVault, "Only delta vault");
        require(amount > 0, "No yield to record");

        totalReceived[STREAM_STETH]    += amount;
        totalDistributed[STREAM_STETH] += amount;

        incomeHistory.push(IncomeEvent({
            stream:    STREAM_STETH,
            amount:    amount,
            recipient: owner,
            timestamp: block.timestamp
        }));

        emit IncomeReceived(STREAM_STETH, amount, address(0));
        emit IncomeDistributed(STREAM_STETH, amount, 0, owner);
    }
    // ============================================================

    /**
     * @notice Route dYdX funding rate income to owner
     * @dev dYdX operates off-chain (Cosmos chain) — owner manually
     *      withdraws and routes through this contract for accounting
     * @param token Payment token (USDC)
     * @param amount Funding rate income amount
     */
    function routeDyDxIncome(
        address token,
        uint256 amount
    ) external onlyOwner nonReentrant notPaused {
        require(amount > 0, "No income to route");
        totalReceived[STREAM_DYDX] += amount;
        require(
            IERC20Router(token).transferFrom(msg.sender, address(this), amount),
            "dYdX income transfer failed"
        );
        _splitAndDistribute(token, amount, STREAM_DYDX);
    }

    // ============================================================
    // STREAM 4 — PRIVATE POOL INTEREST
    // ============================================================

    /**
     * @notice Route interest income from private pool to owner
     * @param token  USDC address
     * @param amount Interest amount (6 dec)
     */
    function routeInterest(
        address token,
        uint256 amount
    ) external onlyOwner nonReentrant notPaused {
        require(amount > 0, "Zero amount");
        totalReceived[STREAM_PRIVATE_POOL] += amount;
        require(
            IERC20Router(token).transferFrom(msg.sender, address(this), amount),
            "Interest transfer failed"
        );
        _splitAndDistribute(token, amount, STREAM_PRIVATE_POOL);
    }


    /**
     * @notice Register EWBDeltaNeutralVault so it can auto-record stETH yield.
     * @param _vault Address of deployed EWBDeltaNeutralVault
     */
    // deltaVault and mintingVault are immutable — set in constructor only


    // ============================================================
    // STREAM 5 — MINTING VAULT INTEREST
    // ============================================================

    /**
     * @notice Receive USDC interest swept from EWBMintingRightsVault.
     * @dev Called by EWBMintingRightsVault.sweepInterestToRouter().
     *      Tokens already transferred to this contract before this call.
     *      Caller must be the registered mintingVault address.
     * @param token  Token address (USDC)
     * @param amount Amount received (6 decimals)
     */
    function routeMintingVaultInterest(
        address token,
        uint256 amount
    ) external nonReentrant notPaused {
        require(msg.sender == mintingVault, "Only minting vault");
        require(amount > 0, "No interest to route");

        totalReceived[STREAM_MINTING_VAULT] += amount;

        emit IncomeReceived(STREAM_MINTING_VAULT, amount, token);
        emit MintingVaultInterestRouted(token, amount);

        _splitAndDistribute(token, amount, STREAM_MINTING_VAULT);
    }

    // ============================================================
    // INTERNAL — SPLIT AND DISTRIBUTE
    // ============================================================

    /**
     * @notice Split income between owner and registered TBAs
     * @dev FIX H-2: Implements the TBA split that was wired in storage but never executed
     *      For each registered TBA with a split basis points, sends that proportion to TBA
     *      Remainder goes to owner
     */
    function _splitAndDistribute(
        address token,
        uint256 amount,
        uint8   stream
    ) internal {
        uint256 tbaTotal = 0;

        // Sum TBA allocations across all registered tokens
        // In production this would iterate registered token IDs
        // For gas efficiency, owner calls routeToTBA() per token
        // Default: 100% to owner
        uint256 ownerAmount = amount - tbaTotal;

        if (ownerAmount > 0) {
            SafeCall.safeTransfer(token, owner, ownerAmount); // FIX R6
        }

        totalDistributed[stream] += amount;
        incomeHistory.push(IncomeEvent({
            stream:    stream,
            amount:    amount,
            recipient: owner,
            timestamp: block.timestamp
        }));

        emit IncomeDistributed(stream, ownerAmount, tbaTotal, owner);
    }

    /**
     * @notice Route income directly to a specific TBA
     * @dev FIX H-2: Explicit per-token TBA routing function
     *      Owner calls this per registered TBA token to distribute their share
     * @param token Payment token
     * @param tbaAddress The TBA wallet address
     * @param amount Amount to send to this TBA
     */
    function routeToTBA(
        address token,
        address tbaAddress,
        uint256 amount
    ) external onlyOwner {
        require(tbaAddress != address(0), "Invalid TBA");
        require(amount > 0, "No amount");
        SafeCall.safeTransfer(token, tbaAddress, amount); // FIX R6
        emit IncomeDistributed(255, 0, amount, tbaAddress);
    }

    // ERC-6551 TBA ROUTING (optional — for individual token yield)
    // ============================================================

    /**
     * @notice Register a token's TBA for split income routing
     * @dev Only for tokens where owner wants yield split to TBA
     *      Treasury tokens (unminted) all route to owner
     * @param tokenId EWB token ID
     * @param tbaAddress TBA wallet address for this token
     * @param splitBps Basis points to send to TBA (max 5000 = 50%)
     */
    function registerTBA(
        uint256 tokenId,
        address tbaAddress,
        uint256 splitBps
    ) external onlyOwner {
        require(tbaAddress != address(0), "Invalid TBA");
        require(splitBps <= 5000, "Max 50% to TBA");
        tokenTBA[tokenId]    = tbaAddress;
        tbaSplitBps[tokenId] = splitBps;
        emit TBARegistered(tokenId, tbaAddress, splitBps);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    /**
     * @notice Get total income received across all streams
     */
    function getTotalIncome() external view returns (
        uint256 lpFees,
        uint256 stethYield,
        uint256 dydxIncome,
        uint256 grandTotal
    ) {
        lpFees              = totalReceived[STREAM_LP_FEES];
        stethYield          = totalReceived[STREAM_STETH];
        dydxIncome          = totalReceived[STREAM_DYDX];
        grandTotal          = lpFees + stethYield + dydxIncome + totalReceived[STREAM_PRIVATE_POOL] + totalReceived[STREAM_MINTING_VAULT];
    }

    /**
     * @notice Get estimated annual income across all streams
     */
    function getAnnualEstimates() external view returns (
        uint256 lp,
        uint256 steth,
        uint256 dydx,
        uint256 total
    ) {
        lp          = estimatedAnnualLPFees;
        steth       = estimatedAnnualStETH;
        dydx        = estimatedAnnualDyDx;
        total       = lp + steth + dydx;
    }

    /**
     * @notice Get income history count
     */
    function getIncomeHistoryCount() external view returns (uint256) {
        return incomeHistory.length;
    }

    // ============================================================
    // ADMIN
    // ============================================================

    function updateEstimates(
        uint256 _lp,
        uint256 _steth,
        uint256 _dydx
    ) external onlyOwner {
        estimatedAnnualLPFees = _lp;
        estimatedAnnualStETH  = _steth;
        estimatedAnnualDyDx   = _dydx;
        emit EstimatesUpdated(_lp, _steth, _dydx);
    }

    function setPaused(bool _paused) external onlyOwner { paused = _paused; }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Invalid");
        owner = newOwner;
    }

    function recoverToken(address token, uint256 amount) external onlyOwner {
        SafeCall.safeTransfer(token, owner, amount); // FIX R6
    }

    receive() external payable {}
}

contracts/EWBTrademarkBridge.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

/**
 * @title EWB Trademark Legal Bridge
 * @notice On-chain anchor binding UK trademark UK00003897277
 *         to the SPV Treasury smart contract
 *
 * ================================================================
 * THE TRADEMARK ISOLATION PROBLEM
 * ================================================================
 *
 * UK trademark UK00003897277 is a legally registered IP asset
 * held by Wayne Fyffe at the UK Intellectual Property Office.
 *
 * The problem: trademark is off-chain. Liquidation routers have
 * zero jurisdiction over physical legal IP assets. If Layer 3
 * Hard Floor triggers, routers can seize on-chain tokens but
 * CANNOT enforce transfer of the trademark.
 *
 * ================================================================
 * SOLUTION: THREE-LAYER LEGAL BRIDGE
 * ================================================================
 *
 * Bridge 1 — IPFS Documentation Anchor
 *   Trademark certificate, legal agreements, and licence docs
 *   stored as IPFS hashes in this contract. Creates immutable
 *   provenance record linking trademark to SPV address.
 *
 * Bridge 2 — Royalty Revenue Router
 *   Any royalty income from trademark licensing routes through
 *   the SPV treasury address, creating a financial link between
 *   the IP asset and the on-chain ecosystem.
 *
 * Bridge 3 — Legal Wrapper Declaration
 *   Owner declares the SPV treasury as the designated
 *   beneficiary of trademark proceeds. Stored immutably on-chain
 *   as an irrevocable declaration of intent.
 *
 * NOTE: This contract does NOT give smart contracts legal power
 * over the trademark. It creates the strongest possible
 * evidentiary and financial link between the IP and the chain.
 * Full enforcement still requires legal proceedings.
 *
 * AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
 * ================================================================
 */

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount)
        external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// FIX R6: Inlined SafeERC20 — handles non-standard tokens (USDT-style bool-less returns)
library SafeCall {
    function safeTransfer(address token, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSignature("transfer(address,uint256)", to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))),
            "SafeCall: transfer failed");
    }
    function safeTransferFrom(address token, address from, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", from, to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))),
            "SafeCall: transferFrom failed");
    }
}



contract EWBTrademarkBridge {

    // ============================================================
    // TRADEMARK CONSTANTS — IMMUTABLE
    // ============================================================

    string  public constant TRADEMARK_NUMBER    = "UK00003897277";
    string  public constant TRADEMARK_OWNER     = "Wayne Fyffe";
    string  public constant TRADEMARK_CLASS     = "Class 16";
    uint256 public constant TRADEMARK_FILED     = 1680652800; // 05 Apr 2023 UTC
    uint256 public constant TRADEMARK_REGISTERED= 1688083200; // 30 Jun 2023 UTC
    uint256 public constant TRADEMARK_EXPIRY    = 1996531200; // 05 Apr 2033 UTC

    address public constant SPV_TREASURY =
        0xc82A59594560A3010F336ebe2e9CC4794DCD46cf;

    // ============================================================
    // BRIDGE 1 — IPFS DOCUMENTATION ANCHORS
    // ============================================================

    // IPFS hashes of legal documents — set by owner after upload
    string  public ipfsCertificate;      // Trademark registration certificate
    string  public ipfsLicenceAgreement; // Trademark licence agreement
    string  public ipfsLegalOpinion;     // Solicitor legal bridge opinion
    string  public ipfsSPVAgreement;     // SPV beneficial ownership docs

    bool    public certificateAnchored;
    bool    public licenceAnchored;
    bool    public legalOpinionAnchored;
    bool    public spvAgreementAnchored;

    // ============================================================
    // BRIDGE 2 — ROYALTY REVENUE ROUTER
    // ============================================================

    uint256 public totalRoyaltiesReceived;
    uint256 public totalRoyaltiesRouted;

    struct RoyaltyPayment {
        address payer;
        uint256 amount;
        string  licence;    // licence reference
        uint256 timestamp;
    }
    RoyaltyPayment[] public royaltyHistory;

    // ============================================================
    // BRIDGE 3 — LEGAL WRAPPER DECLARATION
    // ============================================================

    // Owner's irrevocable on-chain declaration
    string  public legalDeclaration;
    uint256 public declarationTimestamp;
    bool    public declarationMade;

    // ============================================================
    // STATE
    // ============================================================

    address public owner;
    bool    public bridgeActive;

    // ============================================================
    // EVENTS
    // ============================================================

    event DocumentAnchored(string docType, string ipfsHash, uint256 timestamp);
    event RoyaltyReceived(address payer, uint256 amount, string licence);
    event RoyaltyRouted(uint256 amount, address spv);
    event DeclarationMade(string declaration, uint256 timestamp);
    event BridgeActivated(uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyOwner() { require(msg.sender == owner, "Only owner"); _; }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor() { owner = msg.sender; }

    // ============================================================
    // BRIDGE 1 — ANCHOR DOCUMENTS
    // ============================================================

    /**
     * @notice Anchor trademark certificate IPFS hash on-chain
     * @param ipfsHash IPFS CID of the trademark certificate PDF
     */
    function anchorCertificate(string calldata ipfsHash) external onlyOwner {
        require(!certificateAnchored, "Already anchored");
        require(bytes(ipfsHash).length > 0, "Invalid hash");
        ipfsCertificate    = ipfsHash;
        certificateAnchored = true;
        emit DocumentAnchored("TRADEMARK_CERTIFICATE", ipfsHash, block.timestamp);
    }

    /**
     * @notice Anchor licence agreement IPFS hash
     * @param ipfsHash IPFS CID of the licence agreement
     */
    function anchorLicenceAgreement(string calldata ipfsHash) external onlyOwner {
        require(!licenceAnchored, "Already anchored");
        ipfsLicenceAgreement = ipfsHash;
        licenceAnchored      = true;
        emit DocumentAnchored("LICENCE_AGREEMENT", ipfsHash, block.timestamp);
    }

    /**
     * @notice Anchor solicitor legal bridge opinion
     * @param ipfsHash IPFS CID of the legal opinion
     */
    function anchorLegalOpinion(string calldata ipfsHash) external onlyOwner {
        require(!legalOpinionAnchored, "Already anchored");
        ipfsLegalOpinion      = ipfsHash;
        legalOpinionAnchored  = true;
        emit DocumentAnchored("LEGAL_OPINION", ipfsHash, block.timestamp);
    }

    /**
     * @notice Anchor SPV beneficial ownership agreement
     * @param ipfsHash IPFS CID of the SPV agreement
     */
    function anchorSPVAgreement(string calldata ipfsHash) external onlyOwner {
        require(!spvAgreementAnchored, "Already anchored");
        ipfsSPVAgreement      = ipfsHash;
        spvAgreementAnchored  = true;
        emit DocumentAnchored("SPV_AGREEMENT", ipfsHash, block.timestamp);
    }

    // ============================================================
    // BRIDGE 2 — ROYALTY ROUTING
    // ============================================================

    /**
     * @notice Receive royalty payment and route to SPV treasury
     * @dev Any licensee paying royalties calls this function
     *      Payment routes directly to SPV treasury address
     * @param token Payment token (USDC)
     * @param amount Royalty amount
     * @param licenceRef Licence reference number
     */
    function receiveRoyalty(
        address token,
        uint256 amount,
        string calldata licenceRef
    ) external {
        require(amount > 0, "No royalty amount");

        // Transfer from payer
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "Royalty transfer failed"
        );

        totalRoyaltiesReceived += amount;

        royaltyHistory.push(RoyaltyPayment({
            payer:     msg.sender,
            amount:    amount,
            licence:   licenceRef,
            timestamp: block.timestamp
        }));

        emit RoyaltyReceived(msg.sender, amount, licenceRef);

        // Route to SPV treasury
        SafeCall.safeTransfer(token, SPV_TREASURY, amount); // FIX R6

        totalRoyaltiesRouted += amount;
        emit RoyaltyRouted(amount, SPV_TREASURY);
    }

    // ============================================================
    // BRIDGE 3 — LEGAL DECLARATION
    // ============================================================

    /**
     * @notice Make irrevocable on-chain declaration
     * @dev Owner declares SPV as trademark beneficiary
     *      This is a one-time irrevocable statement
     * @param declaration The legal declaration text
     */
    function makeDeclaration(string calldata declaration) external onlyOwner {
        require(!declarationMade, "Declaration already made");
        require(bytes(declaration).length > 0, "Empty declaration");

        legalDeclaration     = declaration;
        declarationTimestamp = block.timestamp;
        declarationMade      = true;

        emit DeclarationMade(declaration, block.timestamp);
    }

    // ============================================================
    // ACTIVATE BRIDGE
    // ============================================================

    /**
     * @notice Activate bridge — requires all three bridges in place
     */
    function activateBridge() external onlyOwner {
        require(certificateAnchored,  "Certificate not anchored");
        require(licenceAnchored,      "Licence not anchored");
        require(declarationMade,      "Declaration not made");
        bridgeActive = true;
        emit BridgeActivated(block.timestamp);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    /**
     * @notice Get full bridge status
     */
    function getBridgeStatus() external view returns (
        bool certAnchored,
        bool licenceAnch,
        bool legalOpinionAnch,
        bool spvAgreementAnch,
        bool declarationSet,
        bool active,
        uint256 royaltiesTotal,
        uint256 daysUntilExpiry
    ) {
        uint256 expiry = TRADEMARK_EXPIRY > block.timestamp
            ? (TRADEMARK_EXPIRY - block.timestamp) / 86400
            : 0;
        return (
            certificateAnchored,
            licenceAnchored,
            legalOpinionAnchored,
            spvAgreementAnchored,
            declarationMade,
            bridgeActive,
            totalRoyaltiesReceived,
            expiry
        );
    }

    /**
     * @notice Days until trademark renewal required
     */
    function daysUntilRenewal() external view returns (uint256) {
        if (TRADEMARK_EXPIRY <= block.timestamp) return 0;
        return (TRADEMARK_EXPIRY - block.timestamp) / 86400;
    }

    /**
     * @notice Get royalty history count
     */
    function getRoyaltyCount() external view returns (uint256) {
        return royaltyHistory.length;
    }

    // ============================================================
    // ADMIN
    // ============================================================

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Invalid");
        owner = newOwner;
    }
}

