// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;
// ================================================================
// VaultCore — deployLongLeg, harvestYield, compoundYield,
//             submitHedgeAttestation, rebalanceHedge
// ================================================================

import "./VaultHedge.sol";

abstract contract VaultCore is VaultHedge {
    //  DEPLOY LONG LEG
    // ------------------------------------------------------------------ //

    /**
     * @notice Deploy ETH from the Safe multisig treasury into the long leg.
     * @dev CAPITAL SOURCE: ETH must come from the Safe multisig treasury only.
     *      Individual NFT holders and end users do NOT call this function and
     *      do NOT send ETH to this contract. See contract header for full
     *      capital flow architecture (Track A vs Track B).
     *
     *      ETH flow: msg.value (from Safe) → stETH (Lido) → wstETH → Aave v3
     *
     *      Step 1: ETH → stETH via Lido submit()
     *      Step 2: stETH → wstETH via IWstETH.wrap() (Aave v3 requires wstETH)
     *      Step 3: wstETH → Aave v3 supply()
     *
     *      maxDeployment cap = LAYER3_ETH_TOTAL (6,391 ETH) from EWBLayer3Token.
     *      This ensures yield strategy never exceeds the NFT collateral backing.
     *
     *      Hedge sizing: bot calls submitHedgeAttestation() after each deploy.
     *      Target: shortNotional == totalDeployed (delta = 0, ±5% tolerance)
     */
    function deployLongLeg() external payable onlyOwner nonReentrant notPaused {
        require(msg.value > 0, "No ETH sent");
        require(totalDeployed + msg.value <= maxDeployment, "Exceeds max deployment");
        require(exitState == ExitState.NORMAL, "Cannot deploy during exit");
        require(!rebalanceRequired, unicode"Hedge drift exceeds threshold — rebalanceHedge() first");
        require(!aavePaused, "Aave is paused");
        require(!lidoQueueAlert, "Lido queue congested");

        // Hard-revert if hedge attestation is stale
        // Cannot deploy new capital without verified hedge state
        (bool fresh, , ) = isHedgeAttestationFresh();
        require(fresh || lastAttestationTime == 0,
            unicode"STALE_HEDGE_ATTESTATION — bot must attest before deploying");

        // Step 1: ETH → stETH
        uint256 stEthReceived = ILido(STETH).submit{value: msg.value}(address(0));
        require(stEthReceived > 0, "Lido: no stETH received");

        totalDeployed += msg.value;
        emit CapitalDeployed(msg.value, stEthReceived);

        // Step 2: stETH → wstETH  (L-2 fix: Aave v3 mainnet requires wstETH)
        IERC20DN(STETH).approve(WSTETH, stEthReceived);
        uint256 wstEthAmount = IWstETH(WSTETH).wrap(stEthReceived);
        require(wstEthAmount > 0, "wstETH: wrap returned zero");

        // Step 3: wstETH → Aave v3
        IERC20DN(WSTETH).approve(AAVE_V3_POOL, wstEthAmount);
        IAaveV3Pool(AAVE_V3_POOL).supply(WSTETH, wstEthAmount, address(this), 0);

        (, , , , , uint256 healthFactor) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));

        emit LongLegOpened(wstEthAmount, healthFactor);
    }

    // recordShortLeg() REMOVED — trust-based recording eliminated.
    // ALL hedge state must go through submitHedgeAttestation()
    // which requires cryptographic signature from registered attestor.
    // No unverified hedge state possible.

    // SIZE FIX: rebalanceLong(uint256,string) REMOVED — it duplicated
    // VaultHedge.rebalanceHedge(uint256,string), which is stricter (it also
    // requires a fresh hedge attestation). Use rebalanceHedge() instead.

    // ------------------------------------------------------------------ //
    //  HARVEST YIELD
    // ------------------------------------------------------------------ //

    /**
     * @notice Harvest stETH yield — PERMISSIONLESS
     * @dev Anyone can trigger harvest when yield >= threshold
     *      Removes owner gate — cannot be blocked by compromised key
     *      Yield always routes to safeMultisig — cannot be redirected
     */
    // FIX-H5 + FIX-QUORUM-HEDGE: harvestYield requires ALL of:
    //   (a) onlyOwner = safeMultisig must sign
    //   (b) hedgeAttestation fresh — if quorum registered, 2-of-3 must have attested
    //   (c) Aave health factor on-chain >= targetHealthFactor
    // Single attestor compromise insufficient when quorum is active.
    // C2-01 FIX: onlyOwner added — harvestYield moves real funds.
    function harvestYield(uint256 yieldAmount) external onlyOwner nonReentrant notPaused {
        // Hard-revert if hedge attestation is stale
        // Harvest without verified hedge = yield without confirmed neutrality
        (bool fresh, , ) = isHedgeAttestationFresh();
        require(fresh, unicode"STALE_HEDGE_ATTESTATION — bot must attest before harvesting");

        require(yieldAmount > 0, "No yield specified");

        (, , , , , uint256 healthFactor) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
        require(healthFactor >= targetHealthFactor, "Health factor too low to harvest");

        // C-08 fix: awstETH balance is in wstETH shares (non-rebasing).
        // Must convert to stETH equivalent before comparing to totalDeployed (ETH).
        uint256 wstEthShares = IAToken(A_WSTETH).balanceOf(address(this));
        uint256 stEthEquiv   = IWstETH(WSTETH).getStETHByWstETH(wstEthShares);
        uint256 yieldAccrued = stEthEquiv > totalDeployed
            ? stEthEquiv - totalDeployed
            : 0;
        require(yieldAmount <= yieldAccrued,
            unicode"Harvest amount exceeds accrued yield — principal protection");

        // C-08 fix: vault holds WSTETH in Aave — withdraw wstETH then unwrap to stETH
        // Convert yieldAmount (stETH) to wstETH shares for withdraw call
        uint256 wstEthToWithdraw = IWstETH(WSTETH).getWstETHByStETH(yieldAmount);
        uint256 wstWithdrawn = IAaveV3Pool(AAVE_V3_POOL).withdraw(
            WSTETH, wstEthToWithdraw, address(this));
        uint256 withdrawn = IWstETH(WSTETH).unwrap(wstWithdrawn);

        totalYieldHarvested += withdrawn;
        lastHarvestTime      = block.timestamp;

        // M-02 fix: only record if under cap
        if (harvestHistory.length < MAX_HISTORY_LENGTH) {
            harvestHistory.push(HarvestRecord({
                timestamp:        block.timestamp,
                yieldAmount:      withdrawn,
                aaveHealthFactor: healthFactor
            }));
        }

        // H-01 fix: transfer to safeMultisig not owner
        SafeERC20DN.safeTransfer(IERC20DN(STETH), safeMultisig, withdrawn); // FIX R6

        // AUTO-RECORD: notify revenue router so income is tracked on-chain
        // without requiring a separate manual multisig call.
        // Silently skips if router not yet set — does not block harvest.
        if (revenueRouter != address(0)) {
            try IEWBRevenueRouter(revenueRouter).recordStETHYieldAuto(withdrawn) {}
            catch {} // non-blocking — harvest succeeds even if router call fails
        }

        emit YieldHarvested(withdrawn, block.timestamp);
    }

    /**
     * @notice Compound accrued yield back into the Aave position.
     * @dev    Reinvests yield WITHOUT withdrawing stETH to safeMultisig.
     *         The wstETH already held by Aave grows via rebase — this
     *         function simply recognises that growth as new principal
     *         and updates totalDeployed so future yield calculations
     *         compound on the larger base.
     *
     *         NO ETH leaves the contract.
     *         NO new ETH is required.
     *         NO existing state is modified except totalDeployed.
     *         ALL existing guards (attestation, health factor, cap)
     *         are identical to deployLongLeg() — dynamic is unchanged.
     *
     *         Recommended: call weekly via keeper bot.
     *         Gas cost: ~$0.03 at current gas prices.
     *
     * @param  compoundAmount  stETH equivalent to recognise as compounded
     *                         principal (must be <= accrued yield)
     */
    function compoundYield(uint256 compoundAmount)
        external
        onlyOwner
        nonReentrant
        notPaused
    {
        require(compoundAmount > 0, "Nothing to compound");

        // Same cap check as deployLongLeg — hard ceiling never moves
        require(
            totalDeployed + compoundAmount <= maxDeployment,
            "Compound would exceed maxDeployment cap"
        );

        // Same attestation check as deployLongLeg — hedge must be verified
        (bool fresh, , ) = isHedgeAttestationFresh();
        require(fresh, unicode"STALE_HEDGE_ATTESTATION — attest before compounding");

        // Same health factor check as harvestYield — never compound
        // into an unhealthy position
        (, , , , , uint256 healthFactor) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
        require(
            healthFactor >= targetHealthFactor,
            "Health factor too low to compound"
        );

        // Verify the amount doesn't exceed what has actually accrued.
        // Uses identical logic to harvestYield() — no double-counting.
        uint256 wstEthShares = IAToken(A_WSTETH).balanceOf(address(this));
        uint256 stEthEquiv   = IWstETH(WSTETH).getStETHByWstETH(wstEthShares);
        uint256 yieldAccrued = stEthEquiv > totalDeployed
            ? stEthEquiv - totalDeployed
            : 0;
        require(
            compoundAmount <= yieldAccrued,
            "Compound amount exceeds accrued yield"
        );

        // Recognise yield as new principal — wstETH is already in Aave
        // earning. totalDeployed increases so the next harvest measures
        // yield against a larger base.
        totalDeployed += compoundAmount;

        emit YieldCompounded(compoundAmount, totalDeployed, block.timestamp);
    }

    // ------------------------------------------------------------------ //
    //  REBALANCE LONG
    // ------------------------------------------------------------------ //

    // ── AUTOMATED HEDGE REBALANCE TRIGGER ─────────────────────
    // Replaces manual rebalance. Keeper bot calls checkAndRebalance()
    // every cycle. If drift > rebalanceThreshold: fires HedgeDriftWarning
    // and blocks new deployments until rebalance is recorded.
    // Human still adjusts dYdX — but the on-chain gate enforces it.


    // SIZE FIX: checkAndRebalance() REMOVED — it duplicated
    // VaultHedge.checkHedgeDrift() (identical drift computation, rebalanceRequired
    // flag and HedgeDriftWarning event). Use checkHedgeDrift() instead.

    // SIZE FIX: rebalanceLong(uint256,bool) REMOVED — the "increase" branch is
    // equivalent to deployLongLeg() and the "decrease" branch to
    // withdrawPartial(); both remain available with the same guards. This trims
    // the duplicated Lido/wstETH/Aave supply+withdraw paths from the bytecode.

    // ------------------------------------------------------------------ //
    //  WITHDRAW
    // ------------------------------------------------------------------ //

    // ── WITHDRAWAL TIMELOCK ─────────────────────────────────
    // Prevents instant capital extraction — 24hr delay enforced
    // Emergency exit bypasses timelock (staged pipeline)
    uint256 public withdrawalRequestedAt;

    /// @notice 24-hour delay between requesting and executing a withdrawal.
    ///         Rationale: Aave wstETH withdrawal involves a Lido unbonding queue that
    ///         can take days. 24h gives the Safe multisig time to detect malicious
    ///         withdrawal requests and pause before funds leave.
}

contracts/vault/VaultEmergency.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;
// ================================================================
// VaultEmergency — initiateEmergencyExit, staged exit pipeline,
//                  checkStETHPeg, detectAavePause
// ================================================================

import "./VaultWithdrawal.sol";

abstract contract VaultEmergency is VaultWithdrawal {
    // EMERGENCY EXIT PIPELINE — STAGED + CHECKPOINTED
    // ================================================================
    //
    // Stage 0 → initiateEmergencyExit()   — pauses system, sets EXIT_IN_PROGRESS
    // Stage 1 → executeAaveWithdrawal()   — withdraws wstETH from Aave
    // Stage 2 → executeUnwrapToStETH()    — unwraps wstETH → stETH
    // Stage 3 → executeTransferToDeed()   — sends stETH to deed wallet
    //
    // If any stage stalls > 6 hours → forceAdvanceExitStage() callable by owner
    // Each stage is idempotent — safe to retry on gas failure

    /**
     * @notice Stage 0 — Initiate emergency exit
     * @dev Pauses all operations. Sets EXIT_IN_PROGRESS.
     *      Call this first then execute stages in order.
     */
    function initiateEmergencyExit() external onlyEmergency {
        require(exitState == ExitState.NORMAL, "Exit already in progress");
        paused        = true;
        exitState     = ExitState.EXIT_IN_PROGRESS;
        exitStartedAt = block.timestamp;
        exitStage     = 1;
        emit ExitStageAdvanced(1, block.timestamp);
    }

    /**
     * @notice Stage 1 — Withdraw wstETH from Aave v3
     * @dev Idempotent — safe to retry if gas fails
     *      If Aave is paused, call setAavePaused(true) and wait
     */
    function executeAaveWithdrawal() external onlyEmergency {
        require(exitState == ExitState.EXIT_IN_PROGRESS, "Not in exit");
        require(exitStage == 1, "Wrong exit stage");
        require(!aavePaused, unicode"Aave is paused — cannot withdraw yet");

        try IAaveV3Pool(AAVE_V3_POOL).withdraw(
            WSTETH, type(uint256).max, address(this)
        ) returns (uint256 recovered) {
            require(recovered > 0, "Nothing withdrawn from Aave");
            exitStage = 2;
            emit ExitStageAdvanced(2, block.timestamp);
        } catch Error(string memory reason) {
            // Check if stage is stuck beyond timeout
            if (block.timestamp > exitStartedAt + EXIT_STAGE_TIMEOUT) {
                exitState = ExitState.EXIT_STUCK;
                emit ExitStuck(exitStage, block.timestamp - exitStartedAt);
            }
            revert(string(abi.encodePacked("Aave withdrawal failed: ", reason)));
        }
    }

    /**
     * @notice Stage 2 — Unwrap wstETH to stETH
     * @dev Idempotent — if already unwrapped, moves to stage 3
     */
    function executeUnwrapToStETH() external onlyEmergency {
        require(exitState == ExitState.EXIT_IN_PROGRESS, "Not in exit");
        require(exitStage == 2, "Wrong exit stage");

        uint256 wstBal = IERC20DN(WSTETH).balanceOf(address(this));
        if (wstBal > 0) {
            IWstETH(WSTETH).unwrap(wstBal);
        }
        exitStage = 3;
        emit ExitStageAdvanced(3, block.timestamp);
    }

    /**
     * @notice Stage 3 — Transfer stETH to deed wallet
     * @dev Final stage. Sets EXIT_COMPLETE.
     */
    function executeTransferToDeed() external onlyEmergency {
        require(exitState == ExitState.EXIT_IN_PROGRESS, "Not in exit");
        require(exitStage == 3, "Wrong exit stage");

        uint256 stBal = IERC20DN(STETH).balanceOf(address(this));
        require(stBal > 0, "No stETH to transfer");

        // H-01 fix: transfer to safeMultisig not owner
        SafeERC20DN.safeTransfer(IERC20DN(STETH), safeMultisig, stBal); // FIX R6

        exitRecovered = stBal;
        totalDeployed = 0;
        exitStage     = 4;
        exitState     = ExitState.EXIT_COMPLETE;

        emit EmergencyExit(stBal, safeMultisig); // H-4 FIX: was owner, should be safeMultisig
        emit ExitStageAdvanced(4, block.timestamp);
    }

    /**
     * @notice Force advance a stuck exit stage
     * @dev Only callable after EXIT_STAGE_TIMEOUT has elapsed
     *      Owner must manually handle the stuck stage off-chain
     */
    function forceAdvanceExitStage() external onlyEmergency {
        require(
            exitState == ExitState.EXIT_IN_PROGRESS ||
            exitState == ExitState.EXIT_STUCK,
            "Not in exit"
        );
        require(
            block.timestamp > exitStartedAt + EXIT_STAGE_TIMEOUT,
            unicode"Timeout not reached — wait 6 hours"
        );
        exitState = ExitState.EXIT_IN_PROGRESS;
        exitStage++;
        exitStartedAt = block.timestamp; // Reset timeout for next stage
        emit ExitForceAdvanced(exitStage, msg.sender);
    }

    // SIZE FIX: legacy single-call emergencyExit() REMOVED — it was explicitly
    // marked "for backwards compatibility" and is fully superseded by the staged,
    // checkpointed pipeline above (initiateEmergencyExit → executeAaveWithdrawal →
    // executeUnwrapToStETH → executeTransferToDeed), which is gas-safe and
    // retryable. Removing the duplicated one-shot path trims the bytecode.

    // ── DEPENDENCY FAILURE HANDLERS ─────────────────────────────

    // ── AUTOMATED FAILURE DETECTION ───────────────────────────
    // Keeper bot calls these checks every cycle.
    // Removes human latency from critical safety triggers.

    address public constant CURVE_STETH_POOL =
        0xDC24316b9AE028F1497c275EB9192a3Ea0f67022;

    /**
     * @notice Auto-check stETH peg from Curve pool
     * @dev Keeper calls every cycle. If peg < 0.95 → halt harvest.
     *      If peg < 0.90 → initiate emergency exit automatically.
     *      Removes human latency from depeg response.
     */
    // M-07 fix: removed onlyOwner — keeper bot must be able to call this permissionlessly
    /// @notice Check if stETH is trading at peg vs ETH. Sets stEthDepeg flag if deviation > threshold.
    function checkStETHPeg() external {
        uint256 ethOut = ICurvePool(CURVE_STETH_POOL)
            .get_dy(1, 0, 1e18);

        if (ethOut < 0.90e18) {
            // Critical depeg — auto-initiate emergency exit
            if (exitState == ExitState.NORMAL) {
                paused    = true;
                exitState = ExitState.EXIT_IN_PROGRESS;
                exitStartedAt = block.timestamp;
                exitStage     = 1;
                emit ExitStageAdvanced(1, block.timestamp);
            }
        } else if (ethOut < 0.95e18) {
            // Soft depeg — pause harvest
            if (!paused) {
                paused = true;
            }
        } else {
            // Healthy — clear soft pause if it was from depeg only
            // (hard pauses from owner remain)
        }
    }

    /**
     * @notice Auto-detect Aave pause — TRUSTLESS
     * @dev Anyone can call — reads Aave getUserAccountData()
     *      If Aave is paused the call reverts — we catch and set flag
     *      Removes owner manual setter — cannot be faked
     */
    /// @notice Check if Aave v3 is paused. Sets aavePaused flag. Callable by anyone.
    function detectAavePause() external {
        try IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this))
            returns (uint256, uint256, uint256, uint256, uint256, uint256)
        {
            // Aave responding — clear pause flag
            if (aavePaused) {
                aavePaused = false;
                emit AavePauseCleared(block.timestamp);
            }
        } catch {
            // Aave not responding — mark paused
            if (!aavePaused) {
                aavePaused = true;
                emit AavePauseDetected(block.timestamp);
            }
        }
    }

    // setAavePaused() REMOVED — use detectAavePause() which is trustless

    /**
     * @notice Signal Lido withdrawal queue congestion
     * @dev Owner calls when Lido queue is too long
     *      Halts new stETH submissions but preserves existing positions
     */
    /// @notice Set the Lido queue congestion alert flag.
    /// @param _alert True if Lido withdrawal queue is congested.
    function setLidoQueueAlert(bool _alert) external onlyOwner {
        lidoQueueAlert = _alert;
        if (_alert) emit LidoQueueAlert(block.timestamp);
    }

    // SIZE FIX: getGovernance() REMOVED — unused on-chain and off-chain; the
    // same data is available directly via the safeMultisig() / coldWallet()
    // public getters.

    /// @notice Returns the current emergency exit state and progress.
    function getExitStatus() external view returns (
        ExitState state,
        uint256   stage,
        uint256   startedAt,
        uint256   recovered,
        bool      timedOut,
        bool      aaveIsPaused,
        bool      lidoAlert
    ) {
        return (
            exitState,
            exitStage,
            exitStartedAt,
            exitRecovered,
            exitStartedAt > 0 &&
                block.timestamp > exitStartedAt + EXIT_STAGE_TIMEOUT,
            aavePaused,
            lidoQueueAlert
        );
    }

    // ------------------------------------------------------------------ //
    //  VIEWS
    // ------------------------------------------------------------------ //

    // SIZE FIX: getPositionStatus() REMOVED — unused on-chain and off-chain.
    // The same data is available from getHealthFactor(), getAccruedYield(),
    // totalDeployed(), shortNotional(), totalYieldHarvested() and a direct
    // Aave getUserAccountData() read, so no monitoring capability is lost.

    /// @notice Returns current Aave health factor in WAD (1e18 = 1.0x).
    function getHealthFactor() external view returns (uint256) {
        (, , , , , uint256 healthFactor) =
            IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
        return healthFactor;
    }

    // L-02 fix: convert awstETH shares to stETH equivalent before comparing to totalDeployed
    /// @notice Returns yield accrued since last harvest (aToken balance - totalDeployed).
    function getAccruedYield() external view returns (uint256) {
        uint256 wstEthShares = IAToken(A_WSTETH).balanceOf(address(this));
        uint256 stEthEquiv   = IWstETH(WSTETH).getStETHByWstETH(wstEthShares);
        return stEthEquiv > totalDeployed ? stEthEquiv - totalDeployed : 0;
    }

    // SIZE FIX: getHarvestCount() REMOVED — unused; harvestHistory has an
    // auto-generated public getter and its length is observable off-chain.

    // ================================================================
}

contracts/vault/VaultHedge.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;

// ================================================================
// VaultHedge — Hedge attestation + rebalance logic
// Extracted from VaultCore to reduce EWBDeltaNeutralVault bytecode
// ================================================================

import "./VaultStorage.sol";

abstract contract VaultHedge is VaultStorage {

    // ── ATTESTOR ROTATION ────────────────────────────────────
    address public pendingAttestor;
    uint256 public attestorRotationEta;
    uint256 public constant ATTESTOR_ROTATION_DELAY = 48 hours;

    // ── DRIFT TRACKING ───────────────────────────────────────
    bool    public rebalanceRequired;
    uint256 public lastDriftPct;

    // ── EVENTS ───────────────────────────────────────────────
    event AttestorRotationQueued(address indexed pending, uint256 eta);
    event AttestorRotationExecuted(address indexed oldAttestor, address indexed newAttestor);
    event AttestorRotationCancelled(address indexed pending);

    // ── ATTESTOR MANAGEMENT ──────────────────────────────────

    function setHedgeAttestor(address _attestor) external onlyOwner {
        require(_attestor != address(0), "Invalid attestor");
        require(hedgeAttestor == address(0), unicode"Attestor already set — use rotateHedgeAttestor()");
        emit HedgeAttestorUpdated(hedgeAttestor, _attestor);
        hedgeAttestor = _attestor;
    }

    function queueAttestorRotation(address _newAttestor) external onlyOwner {
        require(_newAttestor != address(0), "Invalid attestor");
        require(_newAttestor != hedgeAttestor, "Same as current attestor");
        pendingAttestor     = _newAttestor;
        attestorRotationEta = block.timestamp + ATTESTOR_ROTATION_DELAY;
        emit AttestorRotationQueued(_newAttestor, attestorRotationEta);
    }

    function executeAttestorRotation() external onlyEmergency {
        require(pendingAttestor != address(0), "No rotation queued");
        require(block.timestamp >= attestorRotationEta, "Timelock not elapsed");
        address old    = hedgeAttestor;
        hedgeAttestor  = pendingAttestor;
        pendingAttestor        = address(0);
        attestorRotationEta    = 0;
        hedgeVerified          = false;
        emit AttestorRotationExecuted(old, hedgeAttestor);
        emit HedgeAttestorUpdated(old, hedgeAttestor);
    }

    // SIZE FIX: setHedgeQuorumAttestors() REMOVED together with the unused
    // 2-of-3 quorum state in VaultStorage (see note there). It set attestor
    // B/C that no code path ever consulted.

    function cancelAttestorRotation() external onlyOwner {
        require(pendingAttestor != address(0), "No rotation queued");
        address cancelled   = pendingAttestor;
        pendingAttestor     = address(0);
        attestorRotationEta = 0;
        emit AttestorRotationCancelled(cancelled);
    }

    // ── ATTESTATION ──────────────────────────────────────────

    function submitHedgeAttestation(
        uint256 _notional,
        uint256 _leverage,
        uint256 _marginUSD,
        uint256 _fundingRateBps,
        string  calldata _accountId,
        uint256 _dataTimestamp,
        bytes32 _nonce,
        bytes   calldata _signature
    ) external {
        require(hedgeAttestor != address(0), "No attestor registered");
        require(msg.sender == hedgeAttestor, "Only registered attestor");

        bytes32 nonceKey = keccak256(abi.encodePacked(hedgeAttestor, _nonce));
        require(!usedAttestationNonces[nonceKey], "Attestation nonce already used");
        usedAttestationNonces[nonceKey] = true;

        require(_dataTimestamp <= block.timestamp, "Data timestamp in future");
        require(block.timestamp - _dataTimestamp <= 15 minutes,
            unicode"Data timestamp too old — must be within 15 minutes");

        bytes32 dataHash = keccak256(abi.encodePacked(
            HedgeAttestationLib.buildHash(
                _notional, _leverage, _marginUSD,
                _fundingRateBps, _dataTimestamp, _accountId
            ),
            _nonce
        ));

        address recovered = HedgeAttestationLib.recoverSigner(dataHash, _signature);
        require(recovered == hedgeAttestor, "Signature does not match attestor");

        require(_notional > 0, "Notional cannot be zero");
        if (totalDeployed > 0) {
            uint256 diff = _notional > totalDeployed
                ? _notional - totalDeployed
                : totalDeployed - _notional;
            require(diff * 100 / totalDeployed <= 20,
                "Attested notional deviates >20% from long");
        }

        {
            (, , , , , uint256 onChainHF) =
                IAaveV3Pool(AAVE_V3_POOL).getUserAccountData(address(this));
            require(onChainHF >= 105e16,
                unicode"F4: Aave HF below 1.05x — attestation rejected (on-chain cross-check)");
            require(onChainHF >= minWithdrawHealthFactor,
                unicode"F4: Aave HF below vault minimum — attestation rejected");
            emit HedgeAaveCrossCheck(onChainHF, _notional, block.timestamp);
        }

        shortNotional       = _notional;
        dydxAccountId       = _accountId;
        shortLeverage       = _leverage;
        shortMarginUSD      = _marginUSD;
        lastFundingRateBps  = _fundingRateBps;
        lastHedgeTime       = block.timestamp;
        lastAttestationTime = block.timestamp;
        lastAttestationHash = dataHash;
        hedgeVerified       = true;

        if (attestationHistory.length < MAX_HISTORY_LENGTH) {
            attestationHistory.push(HedgeSnapshot({
                notional:       _notional,
                leverage:       _leverage,
                marginUSD:      _marginUSD,
                fundingRateBps: _fundingRateBps,
                timestamp:      block.timestamp,
                dataHash:       dataHash,
                attestedBy:     hedgeAttestor
            }));
        }

        emit HedgeAttested(
            hedgeAttestor, _notional, _fundingRateBps,
            dataHash, block.timestamp
        );

        if (totalDeployed > 0) {
            uint256 diff = _notional > totalDeployed
                ? _notional - totalDeployed
                : totalDeployed - _notional;
            uint256 driftPct = diff * 100 / totalDeployed;
            if (driftPct > rebalanceThreshold) {
                rebalanceRequired = true;
                emit HedgeDriftWarning(totalDeployed, _notional, driftPct);
            } else {
                rebalanceRequired = false;
            }
        }
    }

    function isHedgeAttestationFresh() public view returns (
        bool   fresh,
        uint256 age,
        uint256 maxAge
    ) {
        if (lastAttestationTime == 0) return (false, 0, ATTESTATION_MAX_AGE);
        age   = block.timestamp - lastAttestationTime;
        fresh = age <= ATTESTATION_MAX_AGE;
        maxAge = ATTESTATION_MAX_AGE;
    }

    function getAttestationStatus() external view returns (
        bool    fresh,
        uint256 age,
        uint256 lastNotional,
        uint256 lastFunding,
        uint256 lastMargin,
        bytes32 lastHash,
        uint256 historyLength,
        address attestor
    ) {
        (fresh, age, ) = isHedgeAttestationFresh();
        return (
            fresh, age,
            shortNotional, lastFundingRateBps, shortMarginUSD,
            lastAttestationHash, attestationHistory.length, hedgeAttestor
        );
    }

    function rebalanceHedge(
        uint256 _newNotional,
        string calldata _accountId
    ) external onlyOwner {
        (bool fresh, , ) = isHedgeAttestationFresh();
        require(fresh, unicode"STALE_HEDGE_ATTESTATION — submit attestation first");
        require(_newNotional > 0, "Invalid notional");
        require(totalDeployed > 0, "No long leg");

        if (shortNotional > 0) {
            uint256 attestDiff = _newNotional > shortNotional
                ? _newNotional - shortNotional
                : shortNotional - _newNotional;
            require(attestDiff * 100 / shortNotional <= rebalanceThreshold,
                unicode"Notional deviates from last attestation — submit fresh attestation first");
        }

        uint256 diff = _newNotional > totalDeployed
            ? _newNotional - totalDeployed
            : totalDeployed - _newNotional;
        require(diff * 100 / totalDeployed <= rebalanceThreshold,
            "Rebalanced position still outside threshold");

        shortNotional = _newNotional;
        dydxAccountId = _accountId;
        lastHedgeTime = block.timestamp;
        emit PositionRebalanced(totalDeployed, _newNotional);
    }

    // SIZE FIX: getHedgeStatus() REMOVED — unused on-chain and off-chain. The
    // same long/short/delta/drift data is derivable from totalDeployed(),
    // shortNotional() and getAttestationStatus().

    function checkHedgeDrift() external onlyOwner {
        if (totalDeployed == 0 || shortNotional == 0) return;
        uint256 diff = totalDeployed > shortNotional
            ? totalDeployed - shortNotional
            : shortNotional - totalDeployed;
        uint256 driftPct = diff * 100 / totalDeployed;
        lastDriftPct = driftPct;
        if (driftPct > rebalanceThreshold) {
            if (!rebalanceRequired) {
                rebalanceRequired = true;
                emit HedgeDriftWarning(totalDeployed, shortNotional, driftPct);
            }
        } else {
            rebalanceRequired = false;
        }
    }
}

contracts/vault/VaultStorage.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.19;
// ================================================================
// VaultStorage — All state, events, errors, modifiers
// Auditors: read this file first.
// ================================================================

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

// ================================================================
// EWB DELTA-NEUTRAL VAULT — YIELD STRATEGY
// ================================================================
//
// CAPITAL FLOW — IMPORTANT:
//
//   This vault does NOT accept ETH from end users or NFT holders.
//   ETH enters ONLY from the Safe multisig treasury via deployLongLeg().
//
//   The EWB protocol has TWO parallel capital tracks:
//
//   TRACK A — NFT Collateral (token IDs, no ETH sent):
//     tokenIds → EWBWhaleVault.lockMintingRights()
//              → lockId with faceValueETH calculated from tier floors
//              → EWBMintingRightsVault.openLoan()  (USDC lent vs face value LTV)
//              → EWBPrivatePool.seedPool()          (internal credit lines)
//              → EWBNFTHarvestVault.lockNFTs()      (harvest token issuance)
//
//   TRACK B — Delta-Neutral Yield (ETH from Safe treasury only):
//     Safe multisig → deployLongLeg(){value: ethAmount}
//                  → Lido.submit() → stETH
//                  → IWstETH.wrap() → wstETH
//                  → AaveV3Pool.supply() → aWstETH (earning staking yield)
//     dYdX short leg placed manually, attested on-chain via ECDSA.
//
//   THE LINK:
//     maxDeployment = 6,391 ETH = LAYER3_ETH_TOTAL (from EWBLayer3Token)
//     The L3 credit capacity sets the cap on how much ETH can be deployed.
//     This ensures the yield strategy never exceeds the collateral backing.
//
//   WHO SENDS ETH:
//     Only the Safe multisig, from protocol treasury or yield accumulated.
//     Individual NFT holders NEVER send ETH to this contract.
//
// Strategy: Long stETH via Aave v3 (staking yield) + Short ETH perp via dYdX (hedge)
// Net result: Zero market exposure. Yield only.
//
// AUDIT REQUIRED BEFORE MAINNET DEPLOYMENT
// ================================================================

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "../interfaces/IAaveV3Pool.sol";

interface IWstETH {
    function wrap(uint256 stETHAmount) external returns (uint256 wstETHAmount);
    function unwrap(uint256 wstETHAmount) external returns (uint256 stETHAmount);
    function getWstETHByStETH(uint256 stETHAmount) external view returns (uint256);
    function getStETHByWstETH(uint256 wstETHAmount) external view returns (uint256);
}

interface ILido {
    function submit(address _referral) external payable returns (uint256);
}

// FIX: Added aToken interface to read rebase-adjusted balance from Aave
interface IAToken {
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20DN {
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// FIX R6: Safe ERC-20 transfer helper — handles non-standard tokens (USDT-style).
// stETH returns true but use safeTransfer everywhere for future-proofing.
library SafeERC20DN {
    function safeTransfer(IERC20DN token, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) = address(token).call(
            abi.encodeWithSelector(token.transfer.selector, to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))),
            "SafeERC20DN: transfer failed");
    }
}

/**
 * @title HedgeAttestation
 * @notice Verifiable signed attestation of dYdX hedge position
 *
 * HOW IT WORKS:
 * 1. Keeper bot reads dYdX position via API every 15 minutes
 * 2. Bot signs the position data with its private key (ECDSA)
 * 3. Bot calls submitHedgeAttestation() with data + signature
 * 4. Contract verifies signature came from registered attestor (bot)
 * 5. Attestation stored on-chain with block timestamp
 * 6. Anyone can verify: position data + signature + attestor address
 *
 * TRUST MODEL:
 * - Bot private key signs real position data read from dYdX API
 * - Contract verifies signature — cannot be faked without bot key
 * - Attestation timestamp shows freshness — stale = hedge unverified
 * - Moving from "owner says" → "bot cryptographically attested"
 *
 * NOT PERFECT — bot could be compromised
 * IS BETTER — independent verification, on-chain audit trail
 */
library HedgeAttestationLib {
    /**
     * @notice Recover signer address from attestation data + signature
     * @dev Standard Ethereum signed message hash recovery
     */
    function recoverSigner(
        bytes32 dataHash,
        bytes memory signature
    ) internal pure returns (address) {
        bytes32 ethHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash)
        );
        require(signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8   v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid signature v value");
        return ecrecover(ethHash, v, r, s);
    }

    /**
     * @notice Build attestation data hash
     * @dev Hash of all position fields — any field change = different hash
     */
    function buildHash(
        uint256 notional,
        uint256 leverage,
        uint256 marginUSD,
        uint256 fundingRateBps,
        uint256 timestamp,
        string  memory accountId
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(
            "EWB_HEDGE_ATTESTATION_V1",
            notional,
            leverage,
            marginUSD,
            fundingRateBps,
            timestamp,
            accountId
        ));
    }
}

/**
 * ================================================================
 * FORMAL INVARIANTS — verified by audit firm
 * ================================================================
 *
 * INV-1: PRINCIPAL PRESERVATION
 *   totalDeployed must never decrease except via emergencyExit()
 *   or explicit owner withdrawal.
 *   assert: totalDeployed <= ETH sent by Safe multisig via deployLongLeg()
 *   NOTE: this ETH comes from the Safe treasury, NOT from NFT holders.
 *         NFT holders interact via Track A (lockMintingRights → lockId).
 *
 * INV-2: HARVEST NEVER EXCEEDS YIELD + HEDGE MUST BE FRESH
 *   Harvest amount = aTokenBalance - totalDeployed
 *   assert: harvestAmount <= (aTokenBalance - totalDeployed)
 *   assert: isHedgeAttestationFresh() == true before harvest
 *   Principal is never harvested on stale hedge.
 *
 * INV-3: EXIT STATE MONOTONIC
 *   exitStage can only increase (0→1→2→3→4)
 *   except reset to 0 via clearRecovery() after EXIT_COMPLETE
 *   assert: exitStage_after >= exitStage_before || exitStage_after == 0
 *
 * INV-4: SAFE MULTISIG IS SOLE HARVEST RECIPIENT
 *   All harvested stETH transfers to safeMultisig address only
 *   Moving funds from Safe requires 2-of-3 hardware wallet signatures
 *   assert: harvest destination == safeMultisig always
 *
 * INV-5: EMERGENCY EXIT REACHABLE FROM ANY STATE
 *   initiateEmergencyExit() callable when not already in exit
 *   System can never be locked out of emergency exit
 *   assert: exitState != EXIT_IN_PROGRESS || EXIT_STUCK => initiateEmergencyExit() callable
 *
 * ================================================================
 */
interface IEWBRevenueRouter {
    function recordStETHYieldAuto(uint256 amount) external;
}

interface ICurvePool {
    function get_dy(int128 i, int128 j, uint256 dx)
        external view returns (uint256);
}


abstract contract VaultStorage is ReentrancyGuard {
    using SafeERC20DN for IERC20DN;

    address public constant AAVE_V3_POOL =
        0x87870Bca3F3fD6335C3F4ce8392D69350B4fA4E2;
    address public constant STETH =
        0xae7ab96520DE3A18E5e111B5EaAb095312D7fE84;
    address public constant WSTETH =
        0x7f39C581F595B53c5cb19bD0b3f8dA6c935E2Ca0;
    address public constant WETH =
        0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;

    // C-08 fix: awstETH is the correct aToken — vault deposits wstETH not stETH
    // aStETH (0x1982b...) was WRONG — vault holds awstETH on Aave v3 mainnet
    address public constant A_WSTETH =
        0x0B925eD163218f6662a35e0f0371Ac234f9E9371;

    address public owner;
    bool    public paused;

    // ── DEPENDENCY FAILURE STATES ───────────────────────────────
    // Formally specified behavior under external protocol failure
    //
    // AAVE_PAUSED:      Aave v3 has paused withdrawals
    //                   → harvest halted, capital preserved in Aave
    //                   → deed wallet manually resumes when Aave unpauses
    //
    // LIDO_QUEUE:       Lido withdrawal queue congested
    //                   → stETH submission halted
    //                   → existing stETH positions unaffected
    //
    // EXIT_IN_PROGRESS: Emergency exit initiated — pipeline running
    //                   → no new deployments
    //                   → harvest halted
    //                   → only exit functions callable
    //
    // EXIT_STUCK:       Exit pipeline stalled beyond timeout
    //                   → deed wallet force-advance required
    //
    // EXIT_COMPLETE:    All capital recovered to deed wallet
    //                   → system fully halted pending manual restart

    enum ExitState {
        NORMAL,
        EXIT_IN_PROGRESS,
        EXIT_STUCK,
        EXIT_COMPLETE
    }

    ExitState public exitState;
    bool      public aavePaused;      // Aave withdrawal pause detected
    bool      public lidoQueueAlert;  // Lido withdrawal queue congested
    uint256   public exitStartedAt;   // Timestamp when exit initiated
    uint256   public exitStage;       // 0=not started 1=aave 2=unwrap 3=complete
    uint256   public exitRecovered;   // Amount recovered to deed wallet

    /// @notice Maximum time per emergency exit stage before forceAdvanceExit() can be called.
    ///         6 hours gives sufficient time for Aave withdrawal + wstETH unwrap under normal conditions.
    ///         If a stage hangs (Aave paused, Curve pool drained), coldWallet can force-advance after 6h.
    uint256 public constant EXIT_STAGE_TIMEOUT = 6 hours;

    event AavePauseDetected(uint256 timestamp);
    event AavePauseCleared(uint256 timestamp);
    event LidoQueueAlert(uint256 timestamp);
    event ExitStageAdvanced(uint256 stage, uint256 timestamp);
    event ExitStuck(uint256 stage, uint256 elapsed);
    event ExitForceAdvanced(uint256 stage, address by);

    uint256 public totalDeployed;         // ETH deployed in long leg (principal)
    uint256 public totalYieldHarvested;   // Cumulative stETH harvested to deed wallet
    uint256 public lastHarvestTime;       // Timestamp of last harvest
    uint256 public shortNotional;         // ETH notional of dYdX short leg
    string  public dydxAccountId;         // dYdX account identifier
    uint256 public shortLeverage;         // Leverage ratio x100 (100 = 1x, 200 = 2x)
    uint256 public shortMarginUSD;        // Margin posted in USD cents
    uint256 public lastHedgeTime;         // Timestamp of last hedge record/rebalance

    // ── HEDGE ATTESTATION ───────────────────────────────────
    // Bot signs real dYdX position data — verified on-chain
    address public hedgeAttestor;         // Primary hedge attestor EOA
    // SIZE FIX / DEAD-CODE REMOVAL: the 2-of-3 hedge-quorum scaffolding
    // (hedgeAttestorB/C, hedgeQuorumVotes/Count/Approved, HEDGE_QUORUM,
    // setHedgeQuorumAttestors) was declared but NEVER enforced —
    // submitHedgeAttestation only ever verified the single primary attestor.
    // It was removed to reclaim bytecode; behaviour is unchanged. If a real
    // multi-attestor quorum is wanted, it must be implemented and re-audited.
    uint256 public lastAttestationTime;   // Timestamp of last verified attestation
    uint256 public lastFundingRateBps;    // Last attested funding rate (basis points)
    bytes32 public lastAttestationHash;   // Hash of last attested position data
    bool    public hedgeVerified;         // True if attestation is fresh (< 4 hours)
    // M-03 fix: nonce registry prevents replay of signed attestations
    mapping(bytes32 => bool) public usedAttestationNonces;
    uint256 public constant ATTESTATION_MAX_AGE = 15 minutes; // FIX R3: was 4 hours — stale hedge state is a risk

    struct HedgeSnapshot {
        uint256 notional;
        uint256 leverage;
        uint256 marginUSD;
        uint256 fundingRateBps;
        uint256 timestamp;
        bytes32 dataHash;
        address attestedBy;   // Always == hedgeAttestor — cryptographically verified
    }

    HedgeSnapshot[] public attestationHistory; // On-chain audit trail

    // M-02 fix: cap history arrays to prevent unbounded gas growth
    uint256 public constant MAX_HISTORY_LENGTH = 500;

    uint256 public maxDeployment      = 6_391 ether; // Max = full Layer 3 credit capacity
    uint256 public targetHealthFactor = 2e18;         // Target Aave health factor
    uint256 public rebalanceThreshold = 5;            // Max drift % before rebalance required

    // FIX: Minimum health factor required before a partial withdrawal is allowed
    uint256 public minWithdrawHealthFactor = 15e17; // 1.5x

    struct HarvestRecord {
        uint256 timestamp;
        uint256 yieldAmount;
        uint256 aaveHealthFactor;
    }

    HarvestRecord[] public harvestHistory;

    event CapitalDeployed(uint256 ethAmount, uint256 stEthReceived);
    event LongLegOpened(uint256 wstEthSupplied, uint256 aaveHealthFactor);
    event YieldHarvested(uint256 amount, uint256 timestamp);
    event YieldCompounded(uint256 amount, uint256 newTotalDeployed, uint256 timestamp);
    event PositionRebalanced(uint256 longNotional, uint256 shortNotional);
    event HedgeDriftWarning(uint256 longETH, uint256 shortETH, uint256 driftPct);
    event HedgeAttested(address attestor, uint256 notional, uint256 fundingRateBps,
        bytes32 dataHash, uint256 timestamp);
    /// @notice Emitted on every attestation with the live Aave HF for off-chain monitoring.
    ///         Allows detection of divergence between attested hedge state and Aave ground truth.
    event HedgeAaveCrossCheck(uint256 aaveHealthFactor, uint256 attestedNotional, uint256 timestamp);
    event HedgeAttestorUpdated(address oldAttestor, address newAttestor);
    event HedgeAttestationStale(uint256 lastAttestation, uint256 age);
    event CapitalWithdrawn(uint256 amount, address to);
    event EmergencyExit(uint256 recovered, address to);

    // ============================================================
    // TWO-LAYER GOVERNANCE MODEL
    // ============================================================
    //
    // LAYER 1 — SAFE MULTISIG (primary authority)
    //   Address: safeMultisig (set at deploy)
    //   Threshold: 2-of-3
    //   Signer A: Cold hardware wallet (Ledger) — Wayne Fyffe
    //   Signer B: Hardware wallet B (Trezor) — backup
    //   Signer C: Emergency key (cold storage) — recovery only
    //   Used for: all admin actions, parameter changes, deployments
    //   Legal binding: Safe transaction hash = on-chain evidence
    //
    // LAYER 2 — COLD WALLET (emergency single-signer)
    //   Address: coldWallet (set at deploy — same as Signer A)
    //   Used for: emergency exit ONLY if Safe quorum unavailable
    //   Cannot: change parameters, update oracle, modify config
    //   Can: initiateEmergencyExit(), forceAdvanceExitStage()
    //
    // HARVEST — FULLY AUTOMATED (no signer required)
    //   Keeper bot calls harvestYield() — no multisig approval needed
    //   stETH routes to safeMultisig address automatically
    //   Bot is operator only — cannot touch admin functions
    //
    // $211M UTILITY VALUE — SEPARATE FROM HARVEST
    //   EWB ecosystem value is backing context not harvest capital
    //   Harvest runs on deployed ETH only
    //   $211M does not affect harvest calculation
    //   $211M is NOT locked in this contract
    // ============================================================

    address public immutable safeMultisig; // L-2 FIX: immutable — cannot be reassigned post-deploy
    address public coldWallet;   // Emergency only — Signer A = cold hardware wallet
    address public immutable revenueRouter; // EWBRevenueRouter — auto-records yield on harvest

    modifier onlyMultisig() {
        require(msg.sender == safeMultisig,
            unicode"Requires Safe multisig — 2-of-3 signatures");
        _;
    }

    modifier onlyEmergency() {
        require(
            msg.sender == safeMultisig || msg.sender == coldWallet,
            "Requires multisig or cold wallet"
        );
        _;
    }

    modifier notPaused() { require(!paused, "Vault paused"); _; }

    // Keep onlyOwner as alias to onlyMultisig for backwards compatibility
    modifier onlyOwner() {
        require(msg.sender == safeMultisig,
            "Requires Safe multisig");
        _;
    }

    constructor(address _safeMultisig, address _coldWallet, address _revenueRouter) {
        require(_safeMultisig   != address(0), "Invalid Safe address");
        require(_coldWallet     != address(0), "Invalid cold wallet");
        require(_revenueRouter  != address(0), "Invalid revenueRouter");
        safeMultisig    = _safeMultisig;
        coldWallet      = _coldWallet;
        revenueRouter   = _revenueRouter;
        owner           = _safeMultisig; // owner points to Safe
        lastHarvestTime = block.timestamp;
    }

    // ------------------------------------------------------------------ //
}

